import { createHmac } from "crypto";
import { cookies } from "next/headers";
import { cache } from "react";
import { v2AdminClient } from "./supabase";

/**
 * User simulator (dev/admin tooling). Lets a group owner/admin view the app AS
 * another member of an org they administer — invaluable for testing anything only
 * other people can see (notifications, follows, rosters, visibility rules).
 *
 * Security: the `v2_sim_user` cookie is NEVER trusted on its own. Every request
 * re-verifies (via `canSimulate`) that the REAL user is an owner/admin of an org
 * the target belongs to, so a hand-set cookie can't impersonate anyone.
 *
 * Mechanism: the two identity chokepoints — `v2GetUser` (APIs) and
 * `getPlatformContext` (pages) — resolve the EFFECTIVE user id here, so the whole
 * app acts as the simulated user with no per-route changes. The RLS-scoped client
 * stays bound to the real session; v2 reads/writes overwhelmingly go through the
 * service-role client filtered by the effective `userId`, which is what we swap.
 */

export const SIM_USER_COOKIE = "v2_sim_user";

export const getSimUserCookie = cache(async (): Promise<string | null> => {
  const store = await cookies();
  return store.get(SIM_USER_COOKIE)?.value || null;
});

/**
 * May `realUserId` simulate `targetUserId`? Only when the real user is an active
 * owner/admin of some org the target is also an active member of.
 */
export async function canSimulate(
  admin: ReturnType<typeof v2AdminClient>,
  realUserId: string,
  targetUserId: string,
): Promise<boolean> {
  if (!realUserId || !targetUserId || realUserId === targetUserId) return false;

  const { data: adminOrgs } = await admin
    .from("v2_memberships")
    .select("org_id")
    .eq("user_id", realUserId)
    .eq("status", "active")
    .is("archived_at", null)
    .in("role", ["owner", "admin"]);
  const orgIds = (adminOrgs || []).map((m) => m.org_id);
  if (orgIds.length === 0) return false;

  const { data: shared } = await admin
    .from("v2_memberships")
    .select("org_id")
    .eq("user_id", targetUserId)
    .eq("status", "active")
    .is("archived_at", null)
    .in("org_id", orgIds)
    .limit(1);
  return !!(shared && shared.length);
}

export interface EffectiveUser {
  userId: string | null; // who the app acts as (simulated target, or the real user)
  realUserId: string | null; // always the authenticated user
  simulating: boolean;
}

/**
 * Resolve the effective user for an authenticated real user, honoring the sim
 * cookie only when the gate passes. Request-cached so the many callers per request
 * share one gate check.
 */
export const resolveEffectiveUser = cache(async (realUserId: string | null): Promise<EffectiveUser> => {
  if (!realUserId) return { userId: null, realUserId: null, simulating: false };
  const sim = await getSimUserCookie();
  if (!sim || sim === realUserId) return { userId: realUserId, realUserId, simulating: false };
  const ok = await canSimulate(v2AdminClient(), realUserId, sim);
  return ok ? { userId: sim, realUserId, simulating: true } : { userId: realUserId, realUserId, simulating: false };
});

/* ── Time simulator ──────────────────────────────────────────────────────────
 * Override "now" for testing time-gated features. The cookie value is SIGNED
 * (HMAC) so a non-admin can't hand-set it — `v2Now()` runs context-free deep in
 * server code, so we can't re-check admin per call; the signature is the guard.
 * Setting is still gated to org admins at the API. Format: `<iso>~<hmac>`.
 */
export const SIM_AT_COOKIE = "v2_sim_at";

function signSimAt(iso: string): string {
  return createHmac("sha256", process.env.SUPABASE_SERVICE_ROLE_KEY || "").update(iso).digest("hex").slice(0, 32);
}

/** Build the signed cookie value for a chosen ISO datetime. */
export function makeSimAtCookie(iso: string): string {
  return `${iso}~${signSimAt(iso)}`;
}

/** The valid simulated ISO datetime from the cookie, or null. */
export const getSimAt = cache(async (): Promise<string | null> => {
  const store = await cookies();
  const raw = store.get(SIM_AT_COOKIE)?.value;
  if (!raw) return null;
  const i = raw.lastIndexOf("~");
  if (i < 0) return null;
  const iso = raw.slice(0, i);
  const sig = raw.slice(i + 1);
  if (!iso || sig !== signSimAt(iso)) return null;
  const d = new Date(iso);
  return isNaN(d.getTime()) ? null : iso;
});

/** Effective "now" — the simulated time when set (and validly signed), else real. */
export async function v2Now(): Promise<Date> {
  const iso = await getSimAt();
  return iso ? new Date(iso) : new Date();
}

=== supabase.ts (clients) ===
import { createServerClient } from "@supabase/ssr";
import { createClient as createSupabaseClient, type SupabaseClient } from "@supabase/supabase-js";
import { cookies } from "next/headers";

/**
 * Supabase access for the v2 platform. Deliberately self-contained — the new app
 * shares only the Supabase project's auth with the legacy app and imports none of
 * its code. Every helper here is owned by v2.
 *
 * Auth works for BOTH clients from a single path:
 *   - Web: the SSR cookie session (v2ServerClient).
 *   - Native (iOS/Android): a Supabase JWT sent as `Authorization: Bearer <jwt>`.
 * `v2GetUser(request)` resolves either and returns an RLS-scoped client, so the
 * same membership policies protect web and native equally.
 */

const URL = process.env.NEXT_PUBLIC_SUPABASE_URL!;
const ANON = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!;
const SERVICE = process.env.SUPABASE_SERVICE_ROLE_KEY!;

/** RLS-respecting client bound to the web cookie session. */
export async function v2ServerClient() {
  const cookieStore = await cookies();
  return createServerClient(URL, ANON, {
    cookies: {
      getAll() {
        return cookieStore.getAll();
      },
      setAll(cookiesToSet) {
        try {
          cookiesToSet.forEach(({ name, value, options }) =>
            cookieStore.set(name, value, options)
          );
        } catch {
          // Called from a Server Component — safe to ignore; middleware refreshes.
        }
      },
    },
  });
}

/** Service-role client. Server-only; bypasses RLS. Never expose to the browser. */
export function v2AdminClient(): SupabaseClient {
  return createSupabaseClient(URL, SERVICE, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
}

/** RLS-respecting client bound to a bearer token (native app requests). */
export function v2TokenClient(token: string): SupabaseClient {
  return createSupabaseClient(URL, ANON, {
    global: { headers: { Authorization: `Bearer ${token}` } },
    auth: { persistSession: false, autoRefreshToken: false },
  });
}

export interface V2Auth {
  userId: string | null;
  /** The authenticated user (differs from userId only while simulating). */
  realUserId: string | null;
  /** True when acting as another member via the user simulator. */
  simulating: boolean;
  /** RLS-scoped client for the caller (bearer token client, or cookie client). */
  supabase: SupabaseClient;
}

/**
 * Resolve the caller for an API route from either a bearer token (native) or the
 * cookie session (web), and return an RLS-scoped client for them. `userId` is the
 * EFFECTIVE user — the same as the real user unless an authorized simulator is
 * active (see `resolveEffectiveUser`). Privileged writes should still use
 * v2AdminClient() after checking `userId`.
 */
export async function v2GetUser(request: Request): Promise<V2Auth> {
  const header = request.headers.get("authorization") || request.headers.get("Authorization");
  if (header?.startsWith("Bearer ")) {
    // Native (bearer) requests don't carry the sim cookie — no simulation.
    const token = header.slice(7).trim();
    const supabase = v2TokenClient(token);
    const {
      data: { user },
    } = await supabase.auth.getUser();
    return { userId: user?.id ?? null, realUserId: user?.id ?? null, simulating: false, supabase };
  }
  const supabase = await v2ServerClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  const { resolveEffectiveUser } = await import("./simulator");
  const eff = await resolveEffectiveUser(user?.id ?? null);
  return { userId: eff.userId, realUserId: eff.realUserId, simulating: eff.simulating, supabase };
}

import { NextResponse } from "next/server";
import { v2GetUser, v2AdminClient } from "@/lib/v2/supabase";
import { isOrgAdmin } from "@/lib/v2/orgs";

/**
 * PATCH /api/v2/orgs/[id] — update an org's name, brand color, and/or store link.
 * Owner/admin only. Slug is intentionally NOT regenerated on rename (stable URLs).
 * Auth: bearer (native) or cookie (web) via v2GetUser.
 */
export async function PATCH(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;
  const { userId } = await v2GetUser(request);
  if (!userId) {
    return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
  }

  const admin = v2AdminClient();
  if (!(await isOrgAdmin(admin, userId, id))) {
    return NextResponse.json({ error: "Not allowed" }, { status: 403 });
  }

  let body: {
    name?: string;
    primary_color?: string;
    name_display?: string;
    store_url?: string | null;
    store_label?: string | null;
    store_enabled?: boolean;
    system_name?: string;
    member_noun?: string;
    member_noun_plural?: string;
    onboarding_dismissed?: boolean;
  };
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "Invalid body" }, { status: 400 });
  }

  const patch: Record<string, string | null | boolean> = {};
  if (typeof body.name === "string") {
    const name = body.name.trim();
    if (!name) return NextResponse.json({ error: "Name can't be empty" }, { status: 400 });
    if (name.length > 80) return NextResponse.json({ error: "Name is too long" }, { status: 400 });
    patch.name = name;
  }
  if (typeof body.primary_color === "string") {
    if (!/^#[0-9a-fA-F]{6}$/.test(body.primary_color)) {
      return NextResponse.json({ error: "Invalid color" }, { status: 400 });
    }
    patch.primary_color = body.primary_color;
  }
  if (body.name_display !== undefined) {
    if (body.name_display !== "nickname" && body.name_display !== "real") {
      return NextResponse.json({ error: "Invalid name display" }, { status: 400 });
    }
    patch.name_display = body.name_display;
  }
  if (body.store_url !== undefined) {
    const url = (body.store_url || "").trim();
    if (url && !/^https?:\/\/.+/i.test(url)) {
      return NextResponse.json({ error: "Store link must start with http(s)://" }, { status: 400 });
    }
    patch.store_url = url || null;
  }
  if (body.store_label !== undefined) {
    const label = (body.store_label || "").trim();
    patch.store_label = label ? label.slice(0, 60) : null;
  }
  if (typeof body.store_enabled === "boolean") {
    patch.store_enabled = body.store_enabled;
  }
  if (typeof body.system_name === "string") {
    const sys = body.system_name.trim();
    if (!sys) return NextResponse.json({ error: "System name can't be empty" }, { status: 400 });
    if (sys.length > 40) return NextResponse.json({ error: "System name is too long" }, { status: 400 });
    patch.system_name = sys;
  }
  if (typeof body.member_noun === "string") {
    const n = body.member_noun.trim();
    if (!n) return NextResponse.json({ error: "Member label can't be empty" }, { status: 400 });
    if (n.length > 30) return NextResponse.json({ error: "Member label is too long" }, { status: 400 });
    patch.member_noun = n;
  }
  if (typeof body.member_noun_plural === "string") {
    const n = body.member_noun_plural.trim();
    if (!n) return NextResponse.json({ error: "Member label can't be empty" }, { status: 400 });
    if (n.length > 30) return NextResponse.json({ error: "Member label is too long" }, { status: 400 });
    patch.member_noun_plural = n;
  }
  if (typeof body.onboarding_dismissed === "boolean") {
    patch.onboarding_dismissed_at = body.onboarding_dismissed ? new Date().toISOString() : null;
  }
  if (Object.keys(patch).length === 0) {
    return NextResponse.json({ error: "Nothing to update" }, { status: 400 });
  }
  patch.updated_at = new Date().toISOString();

  const { error } = await admin.from("v2_organizations").update(patch).eq("id", id);
  if (error) {
    return NextResponse.json({ error: error.message }, { status: 500 });
  }
  return NextResponse.json({ ok: true });
}
