import { NextResponse } from "next/server";
import { v2GetUser, v2AdminClient } from "@/lib/v2/supabase";
import { isSystemAdmin } from "@/lib/v2/orgs";

/**
 * Platform system-admin management (GH #178). System admins can grant/revoke the
 * flag on any profile. Gated: the REAL caller must already be a system admin (never
 * the simulated user — escalation guard). Service-role writes bypass RLS by design.
 *
 *   POST   { userId }  → grant is_system_admin
 *   DELETE { userId }  → revoke is_system_admin (refused if it empties the tier)
 */
async function requireSystemAdmin(request: Request) {
  const { realUserId } = await v2GetUser(request);
  if (!realUserId) return { error: NextResponse.json({ error: "Not authenticated" }, { status: 401 }) };
  const admin = v2AdminClient();
  if (!(await isSystemAdmin(admin, realUserId))) {
    return { error: NextResponse.json({ error: "Not allowed" }, { status: 403 }) };
  }
  return { admin, realUserId };
}

async function readUserId(request: Request): Promise<string | null> {
  try {
    const body = (await request.json()) as { userId?: string };
    return typeof body.userId === "string" && body.userId ? body.userId : null;
  } catch {
    return null;
  }
}

export async function POST(request: Request) {
  const gate = await requireSystemAdmin(request);
  if (gate.error) return gate.error;
  const { admin } = gate;

  const userId = await readUserId(request);
  if (!userId) return NextResponse.json({ error: "userId is required" }, { status: 400 });

  // The target must have a profile (a real person who has signed in at least once).
  const { data: prof } = await admin.from("v2_profiles").select("id").eq("id", userId).maybeSingle();
  if (!prof) return NextResponse.json({ error: "No such member" }, { status: 404 });

  const { error } = await admin.from("v2_profiles").update({ is_system_admin: true }).eq("id", userId);
  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
  return NextResponse.json({ ok: true });
}

export async function DELETE(request: Request) {
  const gate = await requireSystemAdmin(request);
  if (gate.error) return gate.error;
  const { admin } = gate;

  const userId = await readUserId(request);
  if (!userId) return NextResponse.json({ error: "userId is required" }, { status: 400 });

  // Lockout guard: never let the platform end up with zero system admins.
  const { data: current } = await admin
    .from("v2_profiles")
    .select("id")
    .eq("is_system_admin", true);
  const ids = (current || []).map((r) => r.id);
  if (!ids.includes(userId)) return NextResponse.json({ error: "Not a system admin" }, { status: 400 });
  if (ids.length <= 1) {
    return NextResponse.json({ error: "Can't remove the last system admin" }, { status: 409 });
  }

  const { error } = await admin.from("v2_profiles").update({ is_system_admin: false }).eq("id", userId);
  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
  return NextResponse.json({ ok: true });
}

import Link from "next/link";
import { redirect } from "next/navigation";
import { getPlatformContext } from "@/lib/v2/context";
import { v2AdminClient } from "@/lib/v2/supabase";
import { pickName } from "@/lib/v2/profile";
import styles from "@/app/new/new.module.css";
import PlatformAdmin, { type OrgRow, type Candidate } from "./PlatformAdmin";

const one = <T,>(v: T | T[] | null | undefined): T | null => (Array.isArray(v) ? v[0] ?? null : v ?? null);

function fmtDate(iso: string | null): string {
  if (!iso) return "";
  const d = new Date(iso);
  return d.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
}

/**
 * Platform system-admin console (GH #178). Cross-org "all groups" view plus system
 * admin management. Gated to platform system admins — everyone else bounces to their
 * own landing. Reads via the service-role client because org RLS only exposes groups
 * the viewer belongs to.
 */
export default async function PlatformAdminPage() {
  const ctx = await getPlatformContext();
  if (!ctx) redirect("/new/signup");
  if (!ctx.isSystemAdmin) redirect("/new");

  const admin = v2AdminClient();

  const [{ data: overview }, { data: owners }, { data: profiles }] = await Promise.all([
    admin
      .from("v2_org_overview")
      .select("id, name, slug, logo_url, created_at, creator_name, member_count, event_count, active_event_name")
      .order("created_at", { ascending: false }),
    // Pick one owner per org to offer "view as owner". role='owner', active only.
    admin
      .from("v2_memberships")
      .select("org_id, user_id, member:v2_profiles(display_name, first_name, last_name, nickname)")
      .eq("role", "owner")
      .eq("status", "active")
      .is("archived_at", null),
    // Candidate pool for granting the system-admin flag + the current roster.
    // NOTE: small today; if the profile table ever exceeds 1000 rows, paginate here.
    admin
      .from("v2_profiles")
      .select("id, display_name, first_name, last_name, nickname, avatar_url, is_system_admin")
      .order("display_name", { ascending: true }),
  ]);

  const ownerByOrg = new Map<string, { userId: string; name: string }>();
  for (const o of owners || []) {
    if (ownerByOrg.has(o.org_id)) continue; // first owner wins
    const p = one(o.member);
    ownerByOrg.set(o.org_id, { userId: o.user_id as string, name: pickName(p, "real") });
  }

  const orgs: OrgRow[] = (overview || []).map((o) => {
    const owner = ownerByOrg.get(o.id as string) || null;
    return {
      id: o.id as string,
      name: o.name as string,
      slug: o.slug as string,
      logoUrl: (o.logo_url as string | null) ?? null,
      createdLabel: fmtDate(o.created_at as string | null),
      creatorName: (o.creator_name as string | null) ?? null,
      memberCount: Number(o.member_count ?? 0),
      eventCount: Number(o.event_count ?? 0),
      activeEventName: (o.active_event_name as string | null) ?? null,
      ownerUserId: owner?.userId ?? null,
      ownerName: owner?.name ?? null,
    };
  });

  const candidates: Candidate[] = (profiles || []).map((p) => ({
    userId: p.id as string,
    name: pickName(p, "real"),
    avatarUrl: (p.avatar_url as string | null) ?? null,
    isSystemAdmin: !!p.is_system_admin,
    search: [p.display_name, p.first_name, p.last_name, p.nickname].filter(Boolean).join(" ").toLowerCase(),
  }));

  return (
    <div className={styles.page}>
      <Link href="/new" className={styles.back}>
        <svg width="16" height="16" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden>
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.8} d="M15 19l-7-7 7-7" />
        </svg>
        Your groups
      </Link>
      <h1 className={styles.title}>Platform</h1>
      <p className={styles.lede} style={{ marginTop: 6 }}>
        Every group on the platform, and who can administer it. System admins see and manage all groups.
      </p>

      <div className={styles.rule} />

      <PlatformAdmin orgs={orgs} candidates={candidates} currentUserId={ctx.realUserId} />
    </div>
  );
}

"use client";

import { useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import styles from "@/app/new/new.module.css";
import ConfirmModal from "@/app/new/_components/ConfirmModal";
/* eslint-disable @next/next/no-img-element */

export interface OrgRow {
  id: string;
  name: string;
  slug: string;
  logoUrl: string | null;
  createdLabel: string;
  creatorName: string | null;
  memberCount: number;
  eventCount: number;
  activeEventName: string | null;
  ownerUserId: string | null;
  ownerName: string | null;
}

export interface Candidate {
  userId: string;
  name: string;
  avatarUrl: string | null;
  isSystemAdmin: boolean;
  search: string;
}

type Pending = { kind: "grant" | "revoke"; userId: string; name: string };

const firstName = (n: string | null) => (n || "owner").trim().split(/\s+/)[0] || "owner";

/**
 * Platform system-admin console UI. Lists every group (with "Open" + "View as
 * owner"), and manages the system-admin roster (grant/revoke, confirmed, with a
 * last-admin lockout guard mirrored on the server).
 */
export default function PlatformAdmin({
  orgs,
  candidates,
  currentUserId,
}: {
  orgs: OrgRow[];
  candidates: Candidate[];
  currentUserId: string;
}) {
  const router = useRouter();
  const [busy, setBusy] = useState(false);
  const [q, setQ] = useState("");
  const [pending, setPending] = useState<Pending | null>(null);

  const admins = candidates.filter((c) => c.isSystemAdmin);
  const query = q.trim().toLowerCase();
  const addable = query
    ? candidates.filter((c) => !c.isSystemAdmin && c.search.includes(query)).slice(0, 8)
    : [];

  async function impersonate(o: OrgRow) {
    if (busy || !o.ownerUserId) return;
    setBusy(true);
    try {
      const res = await fetch("/api/v2/sim", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ userId: o.ownerUserId }),
      });
      if (res.ok) window.location.href = `/new/${o.slug}`;
      else setBusy(false);
    } catch {
      setBusy(false);
    }
  }

  async function runPending() {
    if (!pending || busy) return;
    setBusy(true);
    try {
      const res = await fetch("/api/v2/admin/system-admins", {
        method: pending.kind === "grant" ? "POST" : "DELETE",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ userId: pending.userId }),
      });
      if (res.ok) {
        setPending(null);
        setQ("");
        router.refresh();
      }
    } catch {
      /* leave the modal open so the user can retry */
    } finally {
      setBusy(false);
    }
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 28 }}>
      {/* ── All groups ───────────────────────────────────────────────── */}
      <section className={styles.section}>
        <p className={styles.sectionLabel}>All groups ({orgs.length})</p>
        {orgs.length === 0 ? (
          <div className={styles.empty}>
            <p className={styles.emptyTitle}>No groups yet</p>
            <p className={styles.emptyText}>When someone creates a group, it shows up here.</p>
          </div>
        ) : (
          <div className={styles.cards}>
            {orgs.map((o) => (
              <div key={o.id} className={styles.card}>
                <div className={styles.cardHead}>
                  {o.logoUrl ? (
                    <img src={o.logoUrl} alt="" className={styles.monogramImg} />
                  ) : (
                    <span className={styles.monogram}>{o.name.charAt(0).toUpperCase()}</span>
                  )}
                  <div style={{ minWidth: 0 }}>
                    <div className={styles.orgName}>{o.name}</div>
                    <div className={styles.role}>
                      {o.memberCount} {o.memberCount === 1 ? "member" : "members"}, {o.eventCount}{" "}
                      {o.eventCount === 1 ? "event" : "events"}
                    </div>
                  </div>
                </div>

                <p className={styles.roundFormHint} style={{ margin: "10px 0 0" }}>
                  {o.activeEventName ? `Active event: ${o.activeEventName}` : "No active event"}
                  <br />
                  Created {o.createdLabel}
                  {o.creatorName ? ` by ${o.creatorName}` : ""}
                </p>

                <div style={{ display: "flex", gap: 8, marginTop: 14, flexWrap: "wrap" }}>
                  <Link href={`/new/${o.slug}`} className={styles.createBtnGhost}>
                    Open
                  </Link>
                  {o.ownerUserId && (
                    <button
                      type="button"
                      className={styles.createBtn}
                      onClick={() => impersonate(o)}
                      disabled={busy}
                      style={{ opacity: busy ? 0.6 : 1 }}
                    >
                      View as {firstName(o.ownerName)}
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </section>

      {/* ── System admins ────────────────────────────────────────────── */}
      <section className={styles.section}>
        <p className={styles.sectionLabel}>System admins ({admins.length})</p>
        <p className={styles.roundFormHint} style={{ marginTop: -2, marginBottom: 10 }}>
          System admins can see and manage every group on the platform, and view the app as any member.
        </p>

        <div className={styles.memberList}>
          {admins.map((a) => (
            <div key={a.userId} className={styles.memberRow}>
              {a.avatarUrl ? (
                <img src={a.avatarUrl} alt="" className={styles.memberAvatar} />
              ) : (
                <span className={styles.memberAvatar} aria-hidden>
                  {(a.name[0] || "?").toUpperCase()}
                </span>
              )}
              <div className={styles.memberMeta} style={{ minWidth: 0 }}>
                <div className={styles.memberName}>
                  {a.name}
                  {a.userId === currentUserId ? " (you)" : ""}
                </div>
                <div className={styles.memberSub}>System admin</div>
              </div>
              <button
                type="button"
                className={styles.deleteBtn}
                disabled={busy || admins.length <= 1}
                title={admins.length <= 1 ? "Can't remove the last system admin" : undefined}
                onClick={() => setPending({ kind: "revoke", userId: a.userId, name: a.name })}
              >
                Remove
              </button>
            </div>
          ))}
        </div>

        <label className={styles.label} style={{ marginTop: 18 }}>
          Add a system admin
        </label>
        <input
          className={styles.input}
          placeholder="Search members…"
          value={q}
          onChange={(e) => setQ(e.target.value)}
        />
        {query && (
          <div className={styles.simList} style={{ maxHeight: 300, marginTop: 6 }}>
            {addable.map((c) => (
              <button
                key={c.userId}
                type="button"
                className={styles.simMember}
                disabled={busy}
                onClick={() => setPending({ kind: "grant", userId: c.userId, name: c.name })}
              >
                {c.avatarUrl ? (
                  <img src={c.avatarUrl} alt="" className={styles.simMemberAvatar} />
                ) : (
                  <span className={styles.simMemberAvatarFallback}>{(c.name[0] || "?").toUpperCase()}</span>
                )}
                <span className={styles.simMemberName}>{c.name}</span>
              </button>
            ))}
            {addable.length === 0 && <p className={styles.roundFormHint}>No members found.</p>}
          </div>
        )}
      </section>

      <ConfirmModal
        open={!!pending}
        destructive={pending?.kind === "revoke"}
        title={pending?.kind === "revoke" ? "Remove system admin?" : "Make system admin?"}
        message={
          pending?.kind === "revoke"
            ? `${pending?.name} will lose access to the platform console and can no longer manage other groups.`
            : `${pending?.name} will be able to see and manage every group on the platform, and view the app as any member.`
        }
        confirmLabel={pending?.kind === "revoke" ? "Remove" : "Make admin"}
        onConfirm={runPending}
        onCancel={() => (busy ? undefined : setPending(null))}
      />
    </div>
  );
}

