6	import { resolveContestHoles } from "@/lib/v2/contests/holes";
7	import { computeSkins } from "@/lib/v2/contests/skins";
8	import { fmtTime } from "@/lib/v2/schedule";
9	import ContestSettings from "./ContestSettings";
10	import SideGames, { type SideGame } from "./SideGames";
11	import styles from "@/app/new/new.module.css";
12	
13	/**
14	 * Contest overview (#209). The hub for one contest: its when/course, settings,
15	 * and links into the two jobs — Teams and Scoring — each on its own page. Owner/admin.
16	 */
17	
18	function fmtDate(ymd: string | null): string | null {
19	  if (!ymd) return null;
20	  return new Date(ymd + "T00:00:00").toLocaleDateString("en-US", { weekday: "long", month: "long", day: "numeric" });
21	}
22	
23	export default async function ContestDetailPage({ params }: { params: Promise<{ slug: string; eventId: string; contestId: string }> }) {
24	  const { slug, eventId, contestId } = await params;
25	  const ctx = await getPlatformContext();
26	  if (!ctx) redirect("/new/signup");
27	  const org = ctx.orgs.find((o) => o.slug === slug);
28	  if (!org || (org.role !== "owner" && org.role !== "admin")) redirect(`/new/${slug}`);
29	
30	  const admin = v2AdminClient();
31	  const { data: contestRow } = await admin
32	    .from("v2_contests").select(CONTEST_SELECT)
33	    .eq("id", contestId).eq("org_id", org.id).eq("event_id", eventId).maybeSingle();
34	  const contest = contestRow as Contest | null;
35	  if (!contest) redirect(`/new/${slug}/admin/events/${eventId}/contests`);
36	
37	  const [{ count: partCount }, { count: teamCount }, { data: courseRows }] = await Promise.all([
38	    admin.from("v2_contest_participants").select("id", { count: "exact", head: true }).eq("contest_id", contestId),
39	    admin.from("v2_scramble_teams").select("id", { count: "exact", head: true }).eq("contest_id", contestId),
40	    admin.from("v2_courses").select("id, name, city, state").order("name"),
41	  ]);
42	  const players = partCount ?? 0;
43	  const numTeams = teamCount ?? 0;
44	
45	  const courses = (courseRows || []).map((c) => ({ id: c.id as string, name: c.name as string, city: (c.city as string) ?? null, state: (c.state as string) ?? null }));
46	  const courseName = contest.course_id ? courses.find((c) => c.id === contest.course_id)?.name ?? null : null;
47	
48	  const isCustomMix = !!(contest.config && (contest.config as { hole_tees?: unknown }).hole_tees);
49	  let teeLabel: string | null = null;
50	  if (isCustomMix) teeLabel = "Custom Tees";
51	  else if (contest.tee_id) {
52	    const { data: tee } = await admin.from("v2_course_tees").select("tee_name, par").eq("id", contest.tee_id).maybeSingle();
53	    teeLabel = tee ? `${tee.tee_name} tee (Par ${tee.par})` : null;
54	  }
55	  const courseLine = courseName ? [courseName, teeLabel].filter(Boolean).join(", ") : null;
56	  const hasTee = !!contest.tee_id;
57	
58	  const dateLabel = fmtDate(contest.contest_date);
59	  const timeLabel = fmtTime(contest.start_time);
60	  const whenLabel = dateLabel && timeLabel ? `${dateLabel} at ${timeLabel}` : dateLabel;
61	  const base = `/new/${slug}/admin/events/${eventId}/contests/${contestId}`;
62	
63	  // Side games (child contests) + their winners, the scramble's players (for the
64	  // winner picker), and the holes (for CTP/LD/LP hole selection).
65	  const { data: sideRows } = await admin
66	    .from("v2_contests")
67	    .select("id, contest_type, name, holes, config, declared_no_winner, sort_order")
68	    .eq("parent_contest_id", contestId)
69	    .order("sort_order");
70	  const sideIds = (sideRows || []).map((s) => s.id);
71	  // Buy-ins live in v2_cost_items (single source of truth, #213) — load them for
72	  // the scramble + its side games.
73	  const buyIns = await loadBuyInCents(admin, [contestId, ...sideIds]);
74	  const { data: sideWinners } = sideIds.length
75	    ? await admin.from("v2_contest_winners").select("contest_id, user_id").in("contest_id", sideIds)
76	    : { data: [] as { contest_id: string; user_id: string | null }[] };
77	  const winnerByContest = new Map<string, string | null>();
78	  for (const w of sideWinners || []) if (!winnerByContest.has(w.contest_id)) winnerByContest.set(w.contest_id, w.user_id);
79	
80	  const scoreHoles = await resolveContestHoles(admin, { tee_id: contest.tee_id, config: contest.config });
81	  const holeInfos = scoreHoles.map((h) => ({ hole_number: h.hole_number, par: h.par, yards: h.yards, tee_color: h.tee_color, tee_name: h.tee_name }));
82	
83	  // Compute skins results (per skins side game) from the scramble's team scores.
84	  const skinsByGame: Record<string, { rows: { team: string; skins: number }[]; pending: number }> = {};
85	  if ((sideRows || []).some((s) => s.contest_type === "skins")) {
86	    const { data: teamRows } = await admin.from("v2_scramble_teams").select("id, name, team_handicap, sort_order").eq("contest_id", contestId).order("sort_order");
87	    const tIds = (teamRows || []).map((t) => t.id);
88	    const { data: scoreRows } = tIds.length
89	      ? await admin.from("v2_scramble_hole_scores").select("team_id, hole_number, strokes").in("team_id", tIds)
90	      : { data: [] as { team_id: string; hole_number: number; strokes: number }[] };
91	    const scoresByTeam: Record<string, Record<number, number>> = {};
92	    for (const s of scoreRows || []) (scoresByTeam[s.team_id] ||= {})[s.hole_number] = s.strokes;
93	    const teamName = new Map((teamRows || []).map((t, i) => [t.id, t.name || `Team ${i + 1}`]));
94	    for (const s of sideRows || []) {
95	      if (s.contest_type !== "skins") continue;
96	      const cfg = (s.config || {}) as { skins_type?: string; carryover?: boolean };
97	      const res = computeSkins(teamRows || [], scoresByTeam, scoreHoles, { net: cfg.skins_type !== "gross", carryover: !!cfg.carryover });
98	      skinsByGame[s.id] = { rows: res.rows.map((r) => ({ team: teamName.get(r.team_id) || "Team", skins: r.skins })), pending: res.pending };
99	    }
100	  }
101	
102	  const initialSideGames: SideGame[] = (sideRows || []).map((s) => ({
103	    id: s.id, contest_type: s.contest_type, name: s.name, holes: s.holes, config: s.config,
104	    entry_amount_cents: buyIns.get(s.id) ?? null, winner_user_id: winnerByContest.get(s.id) ?? null, declared_no_winner: s.declared_no_winner,
105	    skins_results: skinsByGame[s.id] ?? null,
106	  }));
107	
108	  const { data: partProfiles } = await admin
109	    .from("v2_contest_participants").select("v2_profiles!inner(id, display_name, first_name, last_name)").eq("contest_id", contestId);
110	  const playerList = (partProfiles || []).map((r) => {
111	    const p = (r as { v2_profiles: unknown }).v2_profiles as { id: string; display_name: string | null; first_name: string | null; last_name: string | null };
112	    return { user_id: p.id, name: p.display_name || `${p.first_name || ""} ${p.last_name || ""}`.trim() || "Member" };
113	  });
114	
115	  return (
116	    <div className={styles.page}>
117	      <Link href={`/new/${slug}/admin/events/${eventId}/contests`} className={styles.back}>
118	        <svg width="16" height="16" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden>
119	          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.8} d="M15 19l-7-7 7-7" />
120	        </svg>
121	        Contests
122	      </Link>
123	      <div className={styles.titleRow}>
124	        <h1 className={styles.title}>{contest.name}</h1>
125	        <ContestSettings
126	          slug={slug}
127	          orgId={org.id}
128	          eventId={eventId}
129	          contestId={contest.id}
130	          name={contest.name}
131	          contestDate={contest.contest_date}
132	          startTime={contest.start_time}
133	          courseId={contest.course_id}
134	          teeId={contest.tee_id}
135	          courseName={courseName}
136	          entryAmountCents={buyIns.get(contest.id) ?? null}
137	          courses={courses}
138	          config={contest.config}
139	        />
140	      </div>
141	      {whenLabel && <p className={styles.lede} style={{ marginTop: 6 }}>{whenLabel}</p>}
142	      {courseLine ? (
143	        <p className={styles.lede} style={{ marginTop: 2 }}>{courseLine}</p>
144	      ) : (
145	        <p className={styles.dnsHint} style={{ marginTop: 2 }}>No course set — pick one in settings to enable scoring.</p>
146	      )}
147	
148	      <div className={styles.contestDays} style={{ marginTop: 20 }}>
149	        <Link href={`${base}/teams`} className={styles.contestCard} data-setup="1">
150	          <span className={styles.contestCardMain}>
151	            <span className={styles.contestCardTitle}>Teams</span>
152	            <span className={styles.contestCardMeta}>
153	              {numTeams} team{numTeams === 1 ? "" : "s"}, {players} player{players === 1 ? "" : "s"}
154	            </span>
155	          </span>
156	          <svg className={styles.contestChevron} width="18" height="18" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden>
157	            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.8} d="M9 5l7 7-7 7" />
158	          </svg>
159	        </Link>
160	        <Link href={`${base}/scoring`} className={styles.contestCard} data-setup="1">
161	          <span className={styles.contestCardMain}>
162	            <span className={styles.contestCardTitle}>Scoring</span>
163	            <span className={styles.contestCardMeta}>
164	              {!hasTee ? "Set a course + tee first" : numTeams === 0 ? "Build teams first" : "Review the scorecard"}
165	            </span>
166	          </span>
167	          <svg className={styles.contestChevron} width="18" height="18" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden>
168	            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.8} d="M9 5l7 7-7 7" />
169	          </svg>
170	        </Link>
171	      </div>
172	
173	      <SideGames
174	        orgId={org.id}
175	        eventId={eventId}
176	        scrambleId={contest.id}
177	        players={playerList}
178	        holes={holeInfos}
179	        initialSideGames={initialSideGames}
180	      />
181	    </div>
182	  );
183	}
