114	
115	    fetch(`/api/v2/orgs/${orgId}/events/${eventId}/contests/${contestId}/scores`, {
116	      method: "PUT",
117	      headers: { "Content-Type": "application/json" },
118	      body: JSON.stringify({
119	        team_id: tid,
120	        hole_number: n,
121	        strokes,
122	        observations: members.map((uid) => ({ user_id: uid, on_green: players[uid]?.on_green, holed_out: players[uid]?.holed_out })),
123	      }),
124	    }).catch(() => {});
125	  }
126	
127	  function gotoHole(n: number) {
128	    if (editHole != null) commitHole(editHole);
