133	    setEditHole(null);
134	    setEditTeamId(null);
135	  }
136	
137	  const editPar = editHole != null ? holeByNum.get(editHole)?.par ?? 4 : 4;
138	  function incScore(d: number) {
139	    setWScore((v) => (v === "" ? editPar : Math.max(1, Math.min(20, v + d))));
140	  }
141	  function toggleGreen(uid: string) {
142	    setWPlayers((p) => ({ ...p, [uid]: { on_green: !p[uid]?.on_green, holed_out: p[uid]?.holed_out ?? false } }));
143	  }
144	  function toggleHoled(uid: string) {
145	    setWPlayers((p) => {
146	      const turningOn = !p[uid]?.holed_out;
147	      const next: Record<string, PlayerObs> = {};
148	      for (const m of editTeam?.members || []) next[m] = { on_green: p[m]?.on_green ?? false, holed_out: m === uid ? turningOn : false };
149	      return next;
