151	  }
152	
153	  const scoreColor = (strokes: number | undefined, par: number) =>
154	    strokes == null ? undefined : strokes < par ? styles.cscUnder : strokes > par ? styles.cscOver : undefined;
155	
156	  function nine(nums: number[], t: ScoreTeam, label: string) {
157	    const sc = scores[t.id] || {};
158	    const parSub = nums.reduce((s, n) => s + (holeByNum.get(n)?.par ?? 0), 0);
159	    const playedNums = nums.filter((n) => sc[n] != null);
160	    const scoreSub = playedNums.reduce((s, n) => s + sc[n], 0);
161	    return (
162	      <div className={styles.cscNineWrap}>
163	        <div className={styles.cscNine}>
164	          <div className={`${styles.cscHoleCol} ${styles.cscLabelCol}`}>
165	            <span className={styles.cscHoleNum}>Hole</span>
166	            <span className={styles.cscHolePar}>Par</span>
167	            <span className={styles.cscLabelScore} />
168	          </div>
169	          {nums.map((n) => {
170	            const par = holeByNum.get(n)?.par ?? 4;
171	            const val = sc[n];
172	            return (
173	              <button key={n} type="button" className={styles.cscHoleCol} onClick={() => openHole(t.id, n)}>
174	                <span className={styles.cscHoleNum}>{n}</span>
175	                <span className={styles.cscHolePar}>{par}</span>
176	                <span className={`${styles.cscHoleScore} ${scoreColor(val, par) || ""}`} data-empty={val == null || undefined}>{val ?? ""}</span>
177	              </button>
178	            );
179	          })}
180	          <div className={`${styles.cscHoleCol} ${styles.cscHoleColSum}`}>
181	            <span className={styles.cscHoleNum}>{label}</span>
182	            <span className={styles.cscHolePar}>{parSub}</span>
183	            <span className={styles.cscHoleScore}>{playedNums.length ? scoreSub : ""}</span>
184	          </div>
185	        </div>
186	      </div>
187	    );
188	  }
189	
190	  // v1-style score math at the bottom of an open scorecard: OUT + IN = TOT − HDCP = NET.
191	  function mathRow(t: ScoreTeam) {
192	    const sc = scores[t.id] || {};
193	    if (!holes.some((h) => sc[h.hole_number] != null)) {
194	      return <p className={styles.cscNoScores}>No scores entered yet.</p>;
195	    }
196	    const out = front.reduce((s, n) => s + (sc[n] ?? 0), 0);
197	    const inn = back.reduce((s, n) => s + (sc[n] ?? 0), 0);
198	    const tot = out + inn;
199	    const adj = Math.max(0, (t.team_handicap ?? 0) - lowestHcp);
200	    const net = tot - adj;
201	    const stat = (label: string, value: number, strong = false) => (
202	      <span className={styles.cscStat}>
203	        <span className={styles.cscStatLabel}>{label}</span>
