207	    return (
208	      <div className={styles.cscMath}>
209	        {stat("OUT", out)}
210	        <span className={styles.cscOp}>+</span>
211	        {stat("IN", inn)}
212	        <span className={styles.cscOp}>=</span>
213	        {stat("TOT", tot)}
214	        <span className={styles.cscOp}>−</span>
215	        {stat("HDCP", adj)}
216	        <span className={styles.cscOp}>=</span>
217	        {stat("NET", net, true)}
218	      </div>
219	    );
220	  }
221	
222	  const front = holeNums.filter((n) => n <= 9);
223	  const back = holeNums.filter((n) => n >= 10);
224	
225	  if (teams.length === 0) return <p className={styles.dnsHint} style={{ marginTop: 16 }}>Build teams first, then score here.</p>;
226	  if (holes.length === 0) return <p className={styles.dnsHint} style={{ marginTop: 16 }}>Set a course + tee in settings to score (needed for par).</p>;
