249	                <div className={styles.cscAccBody}>
250	                  {nine(front, t, "OUT")}
251	                  {back.length > 0 && nine(back, t, "IN")}
252	                  {mathRow(t)}
253	                </div>
254	              )}
255	            </div>
256	          );
257	        })}
258	      </div>
259	
260	      {/* Per-hole editor */}
261	      <Modal open={editHole != null} title={editHole != null ? `Hole ${editHole}, Par ${editPar}` : ""} onClose={closeEditor}>
262	        {editHole != null && editTeam && (
