268	              <button type="button" className={styles.stepBtn} data-kind="strokes" onClick={() => incScore(1)} aria-label="Higher"><span className={styles.stepGlyph}>+</span></button>
269	              {wScore !== "" && <button type="button" className={styles.cscClear} onClick={() => setWScore("")}>Clear</button>}
270	            </div>
271	
272	            <div className={styles.cscPlayers}>
273	              {editTeam.members.map((uid) => (
274	                <div key={uid} className={styles.cscPlayerRow}>
275	                  <span className={styles.cscPlayerName}>{names[uid] || "Member"}</span>
