-- 00253_v2_options_and_ledger.sql
-- Options layer + per-member ledger (#216, epic #214). Realizes #213's phases 3–4.
--
-- Model: the member-facing money unit is the OPTION — an all-or-nothing opt-in that
-- may bundle many contests (e.g. "Closest to the Pin" = $15 covering 6 daily CTP
-- contests). An option's PRICE is DERIVED from the cost_items linked to it
-- (v2_cost_items.linked_option_id), never stored. Trip Cost is the one special,
-- always-included derived "option" = SUM(cost_items WHERE included_in_trip_cost).
--
-- Charges are DERIVED (trip cost if on_roster + each selected option's current price),
-- so editing a cost_item re-prices everything automatically — no stale stored charges.
-- The ledger below stores only the non-derivable money: payments, credits, manual
-- charges, adjustments. Net balance = derived charges + manual charges − payments.

-- ── Options (member-facing opt-in bundles) ──────────────────────────────────
DROP TABLE IF EXISTS public.v2_options CASCADE;
CREATE TABLE public.v2_options (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id      UUID NOT NULL REFERENCES public.v2_organizations(id) ON DELETE CASCADE,
  event_id    UUID NOT NULL REFERENCES public.v2_events(id)        ON DELETE CASCADE,
  name        TEXT NOT NULL,
  description TEXT,
  -- All-or-nothing checkbox for now; richer types (select/quantity) can come later.
  option_type TEXT NOT NULL DEFAULT 'checkbox' CHECK (option_type IN ('checkbox')),
  sort_order  INTEGER NOT NULL DEFAULT 0,
  created_by  UUID REFERENCES public.v2_profiles(id) ON DELETE SET NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_v2_options_event ON public.v2_options(event_id, sort_order);

-- ── Member selections (which options a member opted into) ────────────────────
DROP TABLE IF EXISTS public.v2_user_option_selections CASCADE;
CREATE TABLE public.v2_user_option_selections (
  id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  event_id   UUID NOT NULL REFERENCES public.v2_events(id)   ON DELETE CASCADE,
  option_id  UUID NOT NULL REFERENCES public.v2_options(id)  ON DELETE CASCADE,
  user_id    UUID NOT NULL REFERENCES public.v2_profiles(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (option_id, user_id)
);
CREATE INDEX idx_v2_option_selections_user ON public.v2_user_option_selections(user_id);
CREATE INDEX idx_v2_option_selections_event ON public.v2_user_option_selections(event_id);

-- ── Ledger (stores ONLY non-derivable money) ────────────────────────────────
DROP TABLE IF EXISTS public.v2_financial_transactions CASCADE;
CREATE TABLE public.v2_financial_transactions (
  id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id       UUID NOT NULL REFERENCES public.v2_organizations(id) ON DELETE CASCADE,
  event_id     UUID NOT NULL REFERENCES public.v2_events(id)        ON DELETE CASCADE,
  user_id      UUID NOT NULL REFERENCES public.v2_profiles(id)      ON DELETE CASCADE,
  type         TEXT NOT NULL CHECK (type IN ('charge', 'payment')),
  -- charge sources: manual | adjustment | expense | contest_entry (à-la-carte add)
  -- payment sources: deposit | winnings | credit | adjustment
  source       TEXT NOT NULL CHECK (source IN ('manual','adjustment','expense','contest_entry','deposit','winnings','credit')),
  amount_cents INTEGER NOT NULL CHECK (amount_cents > 0),  -- direction comes from `type`
  description  TEXT,
  method       TEXT,                                       -- cash | venmo | …
  notes        TEXT,
  created_by   UUID REFERENCES public.v2_profiles(id) ON DELETE SET NULL,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_v2_fin_tx_user ON public.v2_financial_transactions(user_id, event_id);

-- Permissive RLS, API-gated writes (mirrors the rest of v2). Members may read their
-- own money; the API enforces who sees what (never the full breakdown to non-admins).
ALTER TABLE public.v2_options                  ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.v2_user_option_selections   ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.v2_financial_transactions   ENABLE ROW LEVEL SECURITY;
CREATE POLICY "v2_options_all"            ON public.v2_options                FOR ALL TO authenticated USING (true) WITH CHECK (true);
CREATE POLICY "v2_option_selections_all"  ON public.v2_user_option_selections FOR ALL TO authenticated USING (true) WITH CHECK (true);
CREATE POLICY "v2_fin_tx_all"             ON public.v2_financial_transactions FOR ALL TO authenticated USING (true) WITH CHECK (true);

GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.v2_options                TO authenticated, service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.v2_user_option_selections TO authenticated, service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.v2_financial_transactions TO authenticated, service_role;

/**
 * v2 Options + money derivation (#216, epic #214).
 *
 * An Option is the member-facing, all-or-nothing opt-in. Its PRICE is derived from
 * the cost_items linked to it (`v2_cost_items.linked_option_id`) — never stored, so
 * editing a cost_item re-prices automatically. An Option bundles the CONTESTS whose
 * buy-in cost_items are linked to it; selecting it enrolls into all of them (#216
 * slice 2). Trip Cost is the one special derived option = SUM(included_in_trip_cost).
 */

import type { SupabaseClient } from "@supabase/supabase-js";

export const OPTION_SELECT =
  "id, org_id, event_id, name, description, option_type, sort_order, created_at, updated_at";

export interface Option {
  id: string;
  org_id: string;
  event_id: string;
  name: string;
  description: string | null;
  option_type: "checkbox";
  sort_order: number;
  created_at: string;
  updated_at: string;
}

/** Derived price (cents) per option = SUM of the cost_items linked to it. */
export async function loadOptionPrices(admin: SupabaseClient, optionIds: string[]): Promise<Map<string, number>> {
  const out = new Map<string, number>();
  if (!optionIds.length) return out;
  const { data } = await admin
    .from("v2_cost_items")
    .select("linked_option_id, amount_cents")
    .in("linked_option_id", optionIds);
  for (const r of data || []) {
    const oid = r.linked_option_id as string | null;
    if (!oid) continue;
    out.set(oid, (out.get(oid) || 0) + ((r.amount_cents as number) || 0));
  }
  return out;
}

/** Trip Cost (cents) for an event = SUM of cost_items marked included_in_trip_cost. */
export async function tripCostCents(admin: SupabaseClient, eventId: string): Promise<number> {
  const { data } = await admin
    .from("v2_cost_items")
    .select("amount_cents")
    .eq("event_id", eventId)
    .eq("included_in_trip_cost", true);
  return (data || []).reduce((s, r) => s + ((r.amount_cents as number) || 0), 0);
}

/** The contest ids an option bundles (its linked cost_items' source contests/side games). */
export async function optionContestIds(admin: SupabaseClient, optionId: string): Promise<string[]> {
  const { data } = await admin
    .from("v2_cost_items")
    .select("source_id")
    .eq("linked_option_id", optionId)
    .in("source_type", ["contest", "side_game"]);
  return [...new Set((data || []).map((r) => r.source_id as string | null).filter((x): x is string => !!x))];
}

import { NextResponse } from "next/server";
import { v2GetUser, v2AdminClient } from "@/lib/v2/supabase";
import { isOrgAdmin, isOrgMember } from "@/lib/v2/orgs";
import { OPTION_SELECT, loadOptionPrices, type Option } from "@/lib/v2/options";

type Params = Promise<{ id: string; eventId: string }>;

/**
 * Event options (#216). GET returns each option with its DERIVED price (sum of its
 * linked cost_items) and the cost_items it bundles. Any member may read; admins write.
 */
export async function GET(request: Request, { params }: { params: Params }) {
  const { userId } = await v2GetUser(request);
  if (!userId) return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
  const { id: orgId, eventId } = await params;

  const admin = v2AdminClient();
  if (!(await isOrgMember(admin, userId, orgId))) return NextResponse.json({ error: "Not a member" }, { status: 403 });

  const { data: optRows } = await admin
    .from("v2_options").select(OPTION_SELECT).eq("event_id", eventId).order("sort_order");
  const options = (optRows || []) as Option[];
  const ids = options.map((o) => o.id);
  const prices = await loadOptionPrices(admin, ids);

  const { data: itemRows } = ids.length
    ? await admin.from("v2_cost_items").select("id, name, amount_cents, source_type, source_id, linked_option_id").in("linked_option_id", ids)
    : { data: [] as { id: string; name: string; amount_cents: number; source_type: string; source_id: string | null; linked_option_id: string | null }[] };
  const itemsByOption = new Map<string, typeof itemRows>();
  for (const it of itemRows || []) {
    const oid = it.linked_option_id as string;
    (itemsByOption.get(oid) || itemsByOption.set(oid, []).get(oid)!).push(it);
  }

  return NextResponse.json({
    options: options.map((o) => ({ ...o, price_cents: prices.get(o.id) || 0, items: itemsByOption.get(o.id) || [] })),
  });
}

/** Create an option (#216). Admins only. */
export async function POST(request: Request, { params }: { params: Params }) {
  const { userId } = await v2GetUser(request);
  if (!userId) return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
  const { id: orgId, eventId } = await params;

  const admin = v2AdminClient();
  if (!(await isOrgAdmin(admin, userId, orgId))) return NextResponse.json({ error: "Admins only" }, { status: 403 });

  let body: { name?: string; description?: string };
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "Invalid body" }, { status: 400 });
  }
  const name = (body.name || "").trim();
  if (!name) return NextResponse.json({ error: "Name is required" }, { status: 400 });
  if (name.length > 120) return NextResponse.json({ error: "Name is too long" }, { status: 400 });

  const { data: last } = await admin
    .from("v2_options").select("sort_order").eq("event_id", eventId).order("sort_order", { ascending: false }).limit(1).maybeSingle();
  const sort_order = (last?.sort_order ?? -1) + 1;

  const { data, error } = await admin
    .from("v2_options")
    .insert({ org_id: orgId, event_id: eventId, name, description: (body.description || "").trim() || null, sort_order, created_by: userId })
    .select(OPTION_SELECT).single();
  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
  return NextResponse.json({ option: { ...(data as Option), price_cents: 0, items: [] } });
}

import { NextResponse } from "next/server";
import { v2GetUser, v2AdminClient } from "@/lib/v2/supabase";
import { isOrgAdmin } from "@/lib/v2/orgs";
import { OPTION_SELECT, type Option } from "@/lib/v2/options";

type Params = Promise<{ id: string; eventId: string; optionId: string }>;

const EDITABLE = new Set(["name", "description", "sort_order"]);

/** Edit an option (#216). Admins only. */
export async function PATCH(request: Request, { params }: { params: Params }) {
  const { userId } = await v2GetUser(request);
  if (!userId) return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
  const { id: orgId, eventId, optionId } = await params;

  const admin = v2AdminClient();
  if (!(await isOrgAdmin(admin, userId, orgId))) return NextResponse.json({ error: "Admins only" }, { status: 403 });

  let body: Record<string, unknown>;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "Invalid body" }, { status: 400 });
  }
  const patch: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(body)) if (EDITABLE.has(k)) patch[k] = v;
  if ("name" in patch) {
    const n = String(patch.name || "").trim();
    if (!n) return NextResponse.json({ error: "Name can't be empty" }, { status: 400 });
    patch.name = n;
  }
  if ("description" in patch) patch.description = String(patch.description || "").trim() || null;
  if (Object.keys(patch).length === 0) return NextResponse.json({ error: "Nothing to update" }, { status: 400 });
  patch.updated_at = new Date().toISOString();

  const { data, error } = await admin
    .from("v2_options").update(patch).eq("id", optionId).eq("org_id", orgId).eq("event_id", eventId)
    .select(OPTION_SELECT).single();
  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
  return NextResponse.json({ option: data as Option });
}

/** Delete an option (#216). Admins only. Unlinks its cost_items (back to unreconciled)
 *  and cascades member selections via FK. */
export async function DELETE(request: Request, { params }: { params: Params }) {
  const { userId } = await v2GetUser(request);
  if (!userId) return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
  const { id: orgId, eventId, optionId } = await params;

  const admin = v2AdminClient();
  if (!(await isOrgAdmin(admin, userId, orgId))) return NextResponse.json({ error: "Admins only" }, { status: 403 });

  // cost_items.linked_option_id has no FK — null them so they don't dangle.
  await admin.from("v2_cost_items").update({ linked_option_id: null, updated_at: new Date().toISOString() }).eq("linked_option_id", optionId);
  const { error } = await admin.from("v2_options").delete().eq("id", optionId).eq("org_id", orgId).eq("event_id", eventId);
  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
  return NextResponse.json({ ok: true });
}

import Link from "next/link";
import { redirect } from "next/navigation";
import { getPlatformContext } from "@/lib/v2/context";
import { v2AdminClient } from "@/lib/v2/supabase";
import { OPTION_SELECT, loadOptionPrices, type Option } from "@/lib/v2/options";
import OptionsManager, { type OptionData, type OptItem } from "./OptionsManager";
import styles from "@/app/new/new.module.css";

/**
 * Event Options (#216) — the opt-in add-ons members choose. Each option's price is
 * DERIVED from the cost_items bundled into it. Admins build options here and bundle
 * contests/costs; members select them (member-facing selection lands next). Owner/admin.
 */
export default async function EventOptionsPage({ params }: { params: Promise<{ slug: string; eventId: string }> }) {
  const { slug, eventId } = await params;
  const ctx = await getPlatformContext();
  if (!ctx) redirect("/new/signup");
  const org = ctx.orgs.find((o) => o.slug === slug);
  if (!org || (org.role !== "owner" && org.role !== "admin")) redirect(`/new/${slug}`);

  const admin = v2AdminClient();
  const { data: event } = await admin.from("v2_events").select("id, name").eq("id", eventId).eq("org_id", org.id).maybeSingle();
  if (!event) redirect(`/new/${slug}/admin/events`);

  const { data: optRows } = await admin.from("v2_options").select(OPTION_SELECT).eq("event_id", eventId).order("sort_order");
  const options = (optRows || []) as Option[];
  const ids = options.map((o) => o.id);
  const prices = await loadOptionPrices(admin, ids);

  // Every cost_item for the event, split into bundled-by-option vs available
  // (unreconciled: not in Trip Cost, not yet in an option).
  const { data: items } = await admin
    .from("v2_cost_items")
    .select("id, name, amount_cents, source_type, source_id, linked_option_id, included_in_trip_cost")
    .eq("event_id", eventId);
  const bundledByOption = new Map<string, OptItem[]>();
  const available: OptItem[] = [];
  for (const it of items || []) {
    const item: OptItem = { id: it.id as string, name: it.name as string, amount_cents: (it.amount_cents as number) || 0, source_type: it.source_type as string };
    if (it.linked_option_id) (bundledByOption.get(it.linked_option_id as string) || bundledByOption.set(it.linked_option_id as string, []).get(it.linked_option_id as string)!).push(item);
    else if (!it.included_in_trip_cost) available.push(item);
  }
  available.sort((a, b) => a.name.localeCompare(b.name));

  const initialOptions: OptionData[] = options.map((o) => ({
    id: o.id, name: o.name, description: o.description, price_cents: prices.get(o.id) || 0, items: bundledByOption.get(o.id) || [],
  }));

  return (
    <div className={styles.page}>
      <Link href={`/new/${slug}/admin/events/${eventId}`} className={styles.back}>
        <svg width="16" height="16" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden>
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.8} d="M15 19l-7-7 7-7" />
        </svg>
        {event.name}
      </Link>
      <h1 className={styles.title}>Options</h1>
      <p className={styles.lede} style={{ marginTop: 6 }}>
        Opt-in add-ons members choose, all-or-nothing. An option&apos;s price is the sum of the costs bundled into it. Anything not in Trip Cost belongs in an option.
      </p>

      <OptionsManager slug={slug} orgId={org.id} eventId={eventId} initialOptions={initialOptions} initialAvailable={available} />
    </div>
  );
}

"use client";

import { useState } from "react";
import Modal from "@/app/new/_components/Modal";
import ConfirmModal from "@/app/new/_components/ConfirmModal";
import styles from "@/app/new/new.module.css";

export interface OptItem {
  id: string;
  name: string;
  amount_cents: number;
  source_type: string;
}
export interface OptionData {
  id: string;
  name: string;
  description: string | null;
  price_cents: number;
  items: OptItem[];
}

function dollars(cents: number): string {
  return `$${(cents / 100).toLocaleString("en-US", { minimumFractionDigits: cents % 100 === 0 ? 0 : 2, maximumFractionDigits: 2 })}`;
}
const priceOf = (items: OptItem[]) => items.reduce((s, i) => s + i.amount_cents, 0);

/**
 * Build opt-in options and bundle cost items (contests/costs) into each. An option's
 * price is the sum of its bundled items (derived). Reconciling an item into an option
 * moves it out of "available" (it leaves Trip Cost automatically on the server).
 */
export default function OptionsManager({
  slug,
  orgId,
  eventId,
  initialOptions,
  initialAvailable,
}: {
  slug: string;
  orgId: string;
  eventId: string;
  initialOptions: OptionData[];
  initialAvailable: OptItem[];
}) {
  const optionsBase = `/api/v2/orgs/${orgId}/events/${eventId}/options`;
  const costBase = `/api/v2/orgs/${orgId}/events/${eventId}/cost-items`;
  void slug;

  const [options, setOptions] = useState<OptionData[]>(initialOptions);
  const [available, setAvailable] = useState<OptItem[]>(initialAvailable);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [formOpen, setFormOpen] = useState(false);
  const [editing, setEditing] = useState<OptionData | null>(null);
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [addingTo, setAddingTo] = useState<OptionData | null>(null);
  const [confirmDel, setConfirmDel] = useState<OptionData | null>(null);

  function openCreate() { setEditing(null); setName(""); setDescription(""); setError(null); setFormOpen(true); }
  function openEdit(o: OptionData) { setEditing(o); setName(o.name); setDescription(o.description || ""); setError(null); setFormOpen(true); }

  async function submitOption(e: React.FormEvent) {
    e.preventDefault();
    if (busy) return;
    if (!name.trim()) { setError("Name is required"); return; }
    setBusy(true); setError(null);
    try {
      if (editing) {
        const res = await fetch(`${optionsBase}/${editing.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ name: name.trim(), description }) });
        if (!res.ok) { setError((await res.json().catch(() => ({}))).error || "Could not save"); return; }
        const { option } = await res.json();
        setOptions((prev) => prev.map((o) => (o.id === editing.id ? { ...o, name: option.name, description: option.description } : o)));
      } else {
        const res = await fetch(optionsBase, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ name: name.trim(), description }) });
        if (!res.ok) { setError((await res.json().catch(() => ({}))).error || "Could not create"); return; }
        const { option } = await res.json();
        setOptions((prev) => [...prev, { id: option.id, name: option.name, description: option.description, price_cents: 0, items: [] }]);
      }
      setFormOpen(false);
    } finally {
      setBusy(false);
    }
  }

  async function deleteOption(o: OptionData) {
    setBusy(true);
    try {
      const res = await fetch(`${optionsBase}/${o.id}`, { method: "DELETE" });
      if (!res.ok) { setError((await res.json().catch(() => ({}))).error || "Could not delete"); return; }
      // Its bundled items become available again.
      setAvailable((prev) => [...prev, ...o.items].sort((a, b) => a.name.localeCompare(b.name)));
      setOptions((prev) => prev.filter((x) => x.id !== o.id));
      setConfirmDel(null);
    } finally {
      setBusy(false);
    }
  }

  async function setItemOption(item: OptItem, optionId: string | null) {
    const res = await fetch(`${costBase}/${item.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ linked_option_id: optionId }) });
    if (!res.ok) { setError((await res.json().catch(() => ({}))).error || "Could not update"); return false; }
    return true;
  }

  async function linkItem(option: OptionData, item: OptItem) {
    if (busy) return;
    setBusy(true); setError(null);
    try {
      if (!(await setItemOption(item, option.id))) return;
      setAvailable((prev) => prev.filter((i) => i.id !== item.id));
      setOptions((prev) => prev.map((o) => {
        if (o.id !== option.id) return o;
        const items = [...o.items, item];
        return { ...o, items, price_cents: priceOf(items) };
      }));
    } finally {
      setBusy(false);
    }
  }

  async function unlinkItem(option: OptionData, item: OptItem) {
    if (busy) return;
    setBusy(true); setError(null);
    try {
      if (!(await setItemOption(item, null))) return;
      setOptions((prev) => prev.map((o) => {
        if (o.id !== option.id) return o;
        const items = o.items.filter((i) => i.id !== item.id);
        return { ...o, items, price_cents: priceOf(items) };
      }));
      setAvailable((prev) => [...prev, item].sort((a, b) => a.name.localeCompare(b.name)));
    } finally {
      setBusy(false);
    }
  }

  // Keep the add-picker's option reference fresh as items move.
  const addingToLive = addingTo ? options.find((o) => o.id === addingTo.id) || null : null;

  return (
    <div>
      {error && <p className={styles.formError} style={{ marginTop: 12 }}>{error}</p>}

      <div className={styles.titleRow} style={{ marginTop: 18 }}>
        <p className={styles.sectionLabel} style={{ marginBottom: 0 }}>Options ({options.length})</p>
        <button type="button" className={styles.circleAdd} aria-label="Add option" onClick={openCreate}>
          <svg width="15" height="15" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 5v14M5 12h14" /></svg>
        </button>
      </div>

      {options.length === 0 ? (
        <p className={styles.dnsHint} style={{ marginTop: 10 }}>No options yet. Add one, then bundle the contests or costs it covers.</p>
      ) : (
        <div className={styles.finGroups} style={{ marginTop: 10 }}>
          {options.map((o) => (
            <div key={o.id} className={styles.finGroup}>
              <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", gap: 10 }}>
                <p className={styles.finGroupHead} style={{ margin: 0 }}>{o.name}</p>
                <span className={styles.finRowAmount}>{dollars(o.price_cents)}</span>
              </div>
              {o.description && <p className={styles.roundFormHint} style={{ margin: "2px 0 8px" }}>{o.description}</p>}

              {o.items.length === 0 ? (
                <p className={styles.dnsHint} style={{ marginTop: 4 }}>Nothing bundled yet. A $0 option is a free opt-in.</p>
              ) : (
                <div className={styles.memberList} style={{ marginTop: 4 }}>
                  {o.items.map((it) => (
                    <div key={it.id} className={styles.finRow}>
                      <div className={styles.finRowMain}>
                        <span className={styles.finRowName}>{it.name}</span>
                      </div>
                      <span className={styles.finRowAmount}>{dollars(it.amount_cents)}</span>
                      <button type="button" className={styles.removeBtn} onClick={() => unlinkItem(o, it)} disabled={busy} style={{ marginLeft: 8 }}>Remove</button>
                    </div>
                  ))}
                </div>
              )}

              <div style={{ display: "flex", gap: 8, marginTop: 10, flexWrap: "wrap" }}>
                <button type="button" className={styles.createBtnGhost} onClick={() => setAddingTo(o)} disabled={available.length === 0}>
                  Add cost{available.length === 0 ? " (none free)" : ""}
                </button>
                <button type="button" className={styles.createBtnGhost} onClick={() => openEdit(o)}>Edit</button>
                <button type="button" className={styles.deleteBtn} onClick={() => setConfirmDel(o)} disabled={busy}>Delete</button>
              </div>
            </div>
          ))}
        </div>
      )}

      {available.length > 0 && (
        <div className={styles.section} style={{ marginTop: 22 }}>
          <p className={styles.sectionLabel}>Not in Trip Cost, not in an option ({available.length})</p>
          <p className={styles.roundFormHint} style={{ marginTop: -2, marginBottom: 8 }}>
            These costs aren&apos;t charged to anyone yet. Bundle each into an option (or mark it Trip Cost on the Financials screen).
          </p>
          <div className={styles.memberList}>
            {available.map((it) => (
              <div key={it.id} className={styles.finRow}>
                <div className={styles.finRowMain}><span className={styles.finRowName}>{it.name}</span></div>
                <span className={styles.finRowAmount}>{dollars(it.amount_cents)}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Create / edit option */}
      <Modal open={formOpen} title={editing ? "Edit option" : "Add option"} onClose={() => (busy ? undefined : setFormOpen(false))}>
        <form className={styles.form} onSubmit={submitOption}>
          <div className={styles.field}>
            <label className={styles.label}>Name</label>
            <input className={styles.input} value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. Closest to the Pin" maxLength={120} autoFocus />
          </div>
          <div className={styles.field}>
            <label className={styles.label}>Description <span className={styles.optional}>(optional)</span></label>
            <textarea className={styles.textarea} value={description} onChange={(e) => setDescription(e.target.value)} placeholder="What members are opting into" maxLength={300} />
          </div>
          {error && <p className={styles.formError}>{error}</p>}
          <button type="submit" className={styles.createBtn} disabled={busy} style={{ opacity: busy ? 0.6 : 1 }}>
            {busy ? "Saving…" : editing ? "Save option" : "Add option"}
          </button>
        </form>
      </Modal>

      {/* Add a cost to an option */}
      <Modal open={!!addingTo} title={addingTo ? `Add costs to ${addingTo.name}` : ""} onClose={() => (busy ? undefined : setAddingTo(null))}>
        {available.length === 0 ? (
          <p className={styles.dnsHint} style={{ marginTop: 0 }}>Nothing available. Create a contest with a buy-in, or add a manual cost on the Financials screen first.</p>
        ) : (
          <div className={styles.memberList}>
            {available.map((it) => (
              <button
                key={it.id}
                type="button"
                className={styles.memberRowBtn}
                disabled={busy}
                onClick={() => addingToLive && linkItem(addingToLive, it)}
              >
                <div className={styles.memberMeta} style={{ minWidth: 0 }}>
                  <div className={styles.memberName}>{it.name}</div>
                </div>
                <span className={styles.finRowAmount}>{dollars(it.amount_cents)}</span>
              </button>
            ))}
          </div>
        )}
      </Modal>

      <ConfirmModal
        open={!!confirmDel}
        destructive
        title="Delete option?"
        message={confirmDel ? `Remove "${confirmDel.name}"? Its ${confirmDel.items.length} bundled cost${confirmDel.items.length === 1 ? "" : "s"} go back to unassigned, and any member selections are cleared.` : ""}
        confirmLabel="Delete"
        onConfirm={() => confirmDel && deleteOption(confirmDel)}
        onCancel={() => (busy ? undefined : setConfirmDel(null))}
      />
    </div>
  );
}

