/**
 * Platform-managed cost-item categories (#216 follow-up). System admins edit these
 * in the platform console; groups use them as the pick list for manual cost items.
 * Each carries an emoji icon that renders inline (even in a native <select>).
 */

import type { SupabaseClient } from "@supabase/supabase-js";

export const COST_CATEGORY_SELECT = "id, key, label, icon, sort_order, is_active, created_at, updated_at";

export interface CostCategory {
  id: string;
  key: string;
  label: string;
  icon: string | null;
  sort_order: number;
  is_active: boolean;
  created_at: string;
  updated_at: string;
}

/** Ordered categories. Active-only by default (the member/admin pick list). */
export async function loadCostCategories(
  admin: SupabaseClient,
  opts: { includeInactive?: boolean } = {},
): Promise<CostCategory[]> {
  let q = admin.from("v2_cost_categories").select(COST_CATEGORY_SELECT).order("sort_order").order("label");
  if (!opts.includeInactive) q = q.eq("is_active", true);
  const { data } = await q;
  return (data || []) as CostCategory[];
}

import { NextResponse } from "next/server";
import { v2GetUser, v2AdminClient } from "@/lib/v2/supabase";
import { isSystemAdmin } from "@/lib/v2/orgs";
import { COST_CATEGORY_SELECT, loadCostCategories, type CostCategory } from "@/lib/v2/cost-categories";

/** Platform cost categories (#216). System admins only. Managed in /new/admin. */
async function requireSystemAdmin(request: Request) {
  const { realUserId } = await v2GetUser(request);
  if (!realUserId) return { error: NextResponse.json({ error: "Not authenticated" }, { status: 401 }) };
  const admin = v2AdminClient();
  if (!(await isSystemAdmin(admin, realUserId))) return { error: NextResponse.json({ error: "Not allowed" }, { status: 403 }) };
  return { admin };
}

const slugify = (s: string) =>
  s.trim().toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "").slice(0, 40) || "category";

export async function GET(request: Request) {
  const gate = await requireSystemAdmin(request);
  if (gate.error) return gate.error;
  const categories = await loadCostCategories(gate.admin, { includeInactive: true });
  return NextResponse.json({ categories });
}

export async function POST(request: Request) {
  const gate = await requireSystemAdmin(request);
  if (gate.error) return gate.error;
  const { admin } = gate;

  let body: { label?: string; icon?: string };
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "Invalid body" }, { status: 400 });
  }
  const label = (body.label || "").trim();
  if (!label) return NextResponse.json({ error: "Label is required" }, { status: 400 });
  if (label.length > 60) return NextResponse.json({ error: "Label is too long" }, { status: 400 });

  // Unique key from the label (append a number if taken).
  const base = slugify(label);
  const { data: existing } = await admin.from("v2_cost_categories").select("key");
  const taken = new Set((existing || []).map((r) => r.key as string));
  let key = base;
  for (let i = 2; taken.has(key); i++) key = `${base}_${i}`;

  const { data: last } = await admin.from("v2_cost_categories").select("sort_order").order("sort_order", { ascending: false }).limit(1).maybeSingle();
  const sort_order = (last?.sort_order ?? -1) + 1;

  const { data, error } = await admin
    .from("v2_cost_categories")
    .insert({ key, label, icon: (body.icon || "").trim() || null, sort_order })
    .select(COST_CATEGORY_SELECT).single();
  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
  return NextResponse.json({ category: data as CostCategory });
}

import { NextResponse } from "next/server";
import { v2GetUser, v2AdminClient } from "@/lib/v2/supabase";
import { isSystemAdmin } from "@/lib/v2/orgs";
import { COST_CATEGORY_SELECT, type CostCategory } from "@/lib/v2/cost-categories";

type Params = Promise<{ id: string }>;

async function requireSystemAdmin(request: Request) {
  const { realUserId } = await v2GetUser(request);
  if (!realUserId) return { error: NextResponse.json({ error: "Not authenticated" }, { status: 401 }) };
  const admin = v2AdminClient();
  if (!(await isSystemAdmin(admin, realUserId))) return { error: NextResponse.json({ error: "Not allowed" }, { status: 403 }) };
  return { admin };
}

const EDITABLE = new Set(["label", "icon", "sort_order", "is_active"]);

export async function PATCH(request: Request, { params }: { params: Params }) {
  const gate = await requireSystemAdmin(request);
  if (gate.error) return gate.error;
  const { admin } = gate;
  const { id } = await params;

  let body: Record<string, unknown>;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "Invalid body" }, { status: 400 });
  }
  const patch: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(body)) if (EDITABLE.has(k)) patch[k] = v;
  if ("label" in patch) {
    const l = String(patch.label || "").trim();
    if (!l) return NextResponse.json({ error: "Label can't be empty" }, { status: 400 });
    patch.label = l;
  }
  if ("icon" in patch) patch.icon = String(patch.icon || "").trim() || null;
  if (Object.keys(patch).length === 0) return NextResponse.json({ error: "Nothing to update" }, { status: 400 });
  patch.updated_at = new Date().toISOString();

  const { data, error } = await admin.from("v2_cost_categories").update(patch).eq("id", id).select(COST_CATEGORY_SELECT).single();
  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
  return NextResponse.json({ category: data as CostCategory });
}

/** Delete a category — refused if any cost item still uses it (deactivate instead). */
export async function DELETE(request: Request, { params }: { params: Params }) {
  const gate = await requireSystemAdmin(request);
  if (gate.error) return gate.error;
  const { admin } = gate;
  const { id } = await params;

  const { data: cat } = await admin.from("v2_cost_categories").select("key").eq("id", id).maybeSingle();
  if (!cat) return NextResponse.json({ error: "Not found" }, { status: 404 });

  const { count } = await admin.from("v2_cost_items").select("id", { count: "exact", head: true }).eq("category", cat.key);
  if (count && count > 0) {
    return NextResponse.json({ error: `In use by ${count} cost item${count === 1 ? "" : "s"}. Deactivate it instead.` }, { status: 409 });
  }

  const { error } = await admin.from("v2_cost_categories").delete().eq("id", id);
  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
  return NextResponse.json({ ok: true });
}

import Link from "next/link";
import { redirect } from "next/navigation";
import { getPlatformContext } from "@/lib/v2/context";
import { v2AdminClient } from "@/lib/v2/supabase";
import { loadCostCategories } from "@/lib/v2/cost-categories";
import CostCategoriesManager from "./CostCategoriesManager";
import styles from "@/app/new/new.module.css";

/**
 * Platform data management → Cost categories (#216). System admins curate the shared
 * category list every group uses for manual cost items. Gated to system admins.
 */
export default async function CostCategoriesPage() {
  const ctx = await getPlatformContext();
  if (!ctx) redirect("/new/signup");
  if (!ctx.isSystemAdmin) redirect("/new");

  const admin = v2AdminClient();
  const categories = await loadCostCategories(admin, { includeInactive: true });

  return (
    <div className={styles.page}>
      <Link href="/new/admin" className={styles.back}>
        <svg width="16" height="16" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden>
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.8} d="M15 19l-7-7 7-7" />
        </svg>
        Platform
      </Link>
      <h1 className={styles.title}>Cost categories</h1>
      <p className={styles.lede} style={{ marginTop: 6 }}>
        The shared list every group uses to file manual cost items. Each has an emoji icon that shows in the picker. Deactivate a category to retire it without losing history.
      </p>

      <CostCategoriesManager initialCategories={categories} />
    </div>
  );
}

"use client";

import { useState } from "react";
import Modal from "@/app/new/_components/Modal";
import ConfirmModal from "@/app/new/_components/ConfirmModal";
import styles from "@/app/new/new.module.css";
import type { CostCategory } from "@/lib/v2/cost-categories";

/**
 * System-admin editor for the platform cost-category list. Add, rename, re-icon,
 * deactivate, or delete (delete refused while a category is in use — deactivate).
 */
export default function CostCategoriesManager({ initialCategories }: { initialCategories: CostCategory[] }) {
  const base = "/api/v2/admin/cost-categories";
  const [cats, setCats] = useState<CostCategory[]>(initialCategories);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [formOpen, setFormOpen] = useState(false);
  const [editing, setEditing] = useState<CostCategory | null>(null);
  const [label, setLabel] = useState("");
  const [icon, setIcon] = useState("");
  const [confirmDel, setConfirmDel] = useState<CostCategory | null>(null);

  function openCreate() { setEditing(null); setLabel(""); setIcon(""); setError(null); setFormOpen(true); }
  function openEdit(c: CostCategory) { setEditing(c); setLabel(c.label); setIcon(c.icon || ""); setError(null); setFormOpen(true); }

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    if (busy) return;
    if (!label.trim()) { setError("Label is required"); return; }
    setBusy(true); setError(null);
    try {
      if (editing) {
        const res = await fetch(`${base}/${editing.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ label: label.trim(), icon }) });
        if (!res.ok) { setError((await res.json().catch(() => ({}))).error || "Could not save"); return; }
        const { category } = await res.json();
        setCats((prev) => prev.map((c) => (c.id === editing.id ? category : c)));
      } else {
        const res = await fetch(base, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ label: label.trim(), icon }) });
        if (!res.ok) { setError((await res.json().catch(() => ({}))).error || "Could not create"); return; }
        const { category } = await res.json();
        setCats((prev) => [...prev, category]);
      }
      setFormOpen(false);
    } finally {
      setBusy(false);
    }
  }

  async function toggleActive(c: CostCategory) {
    if (busy) return;
    setBusy(true); setError(null);
    try {
      const res = await fetch(`${base}/${c.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ is_active: !c.is_active }) });
      if (!res.ok) { setError((await res.json().catch(() => ({}))).error || "Could not update"); return; }
      const { category } = await res.json();
      setCats((prev) => prev.map((x) => (x.id === c.id ? category : x)));
    } finally {
      setBusy(false);
    }
  }

  async function remove(c: CostCategory) {
    setBusy(true); setError(null);
    try {
      const res = await fetch(`${base}/${c.id}`, { method: "DELETE" });
      if (!res.ok) { setError((await res.json().catch(() => ({}))).error || "Could not delete"); setConfirmDel(null); return; }
      setCats((prev) => prev.filter((x) => x.id !== c.id));
      setConfirmDel(null);
    } finally {
      setBusy(false);
    }
  }

  return (
    <div>
      {error && <p className={styles.formError} style={{ marginTop: 12 }}>{error}</p>}

      <div className={styles.titleRow} style={{ marginTop: 18 }}>
        <p className={styles.sectionLabel} style={{ marginBottom: 0 }}>Categories ({cats.length})</p>
        <button type="button" className={styles.circleAdd} aria-label="Add category" onClick={openCreate}>
          <svg width="15" height="15" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 5v14M5 12h14" /></svg>
        </button>
      </div>

      <div className={styles.memberList} style={{ marginTop: 10 }}>
        {cats.map((c) => (
          <div key={c.id} className={styles.memberRow} style={{ opacity: c.is_active ? 1 : 0.55 }}>
            <span className={styles.memberAvatar} aria-hidden style={{ background: "transparent", fontSize: "1.1rem" }}>{c.icon || "🏷️"}</span>
            <div className={styles.memberMeta} style={{ minWidth: 0 }}>
              <div className={styles.memberName}>{c.label}{!c.is_active && <span className={styles.roleBadge} style={{ marginLeft: 8 }}>inactive</span>}</div>
              <div className={styles.memberSub}>{c.key}</div>
            </div>
            <button type="button" className={styles.createBtnGhost} onClick={() => toggleActive(c)} disabled={busy}>
              {c.is_active ? "Deactivate" : "Activate"}
            </button>
            <button type="button" className={styles.sideEditBtn} aria-label="Edit category" onClick={() => openEdit(c)} style={{ marginLeft: 6 }}>
              <svg width="14" height="14" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" viewBox="0 0 24 24"><path d="M12 20h9" /><path d="M16.5 3.5a2.12 2.12 0 013 3L7 19l-4 1 1-4z" /></svg>
            </button>
          </div>
        ))}
      </div>

      <Modal open={formOpen} title={editing ? "Edit category" : "Add category"} onClose={() => (busy ? undefined : setFormOpen(false))}>
        <form className={styles.form} onSubmit={submit}>
          <div className={styles.profileTwoCol}>
            <div className={styles.field} style={{ flex: "none", width: 90 }}>
              <label className={styles.label}>Icon</label>
              <input className={styles.input} value={icon} onChange={(e) => setIcon(e.target.value)} placeholder="🏷️" maxLength={4} style={{ textAlign: "center" }} />
            </div>
            <div className={styles.field} style={{ flex: 1 }}>
              <label className={styles.label}>Label</label>
              <input className={styles.input} value={label} onChange={(e) => setLabel(e.target.value)} placeholder="e.g. Transportation" maxLength={60} autoFocus />
            </div>
          </div>
          {error && <p className={styles.formError}>{error}</p>}
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            <button type="submit" className={styles.createBtn} disabled={busy} style={{ opacity: busy ? 0.6 : 1 }}>
              {busy ? "Saving…" : editing ? "Save category" : "Add category"}
            </button>
            {editing && (
              <button type="button" className={styles.deleteBtn} onClick={() => { const c = editing; setFormOpen(false); setConfirmDel(c); }} disabled={busy}>
                Delete category
              </button>
            )}
          </div>
        </form>
      </Modal>

      <ConfirmModal
        open={!!confirmDel}
        destructive
        title="Delete category?"
        message={confirmDel ? `Remove "${confirmDel.label}"? If any cost item uses it, deactivate it instead.` : ""}
        confirmLabel="Delete"
        onConfirm={() => confirmDel && remove(confirmDel)}
        onCancel={() => (busy ? undefined : setConfirmDel(null))}
      />
    </div>
  );
}

