"use client";

import { useState } from "react";
import styles from "@/app/new/new.module.css";
import type { OptionType, OptionChoice } from "@/lib/v2/options";

export interface MemberOption {
  id: string;
  name: string;
  description: string | null;
  option_type: OptionType;
  choices: OptionChoice[] | null;
  is_required: boolean;
  max_total: number | null;
  icon: string | null;
  group_id: string | null;
  depends_on_option_id: string | null;
  price_cents: number;
}
export interface MemberGroup { id: string; name: string; icon: string | null }

function dollars(cents: number): string {
  return `$${(cents / 100).toLocaleString("en-US", { minimumFractionDigits: cents % 100 === 0 ? 0 : 2, maximumFractionDigits: 2 })}`;
}

function isEmptyValue(type: OptionType, v: unknown): boolean {
  switch (type) {
    case "checkbox": return v !== true;
    case "select": return !(typeof v === "string" && v.length > 0);
    case "multi_select": return !(Array.isArray(v) && v.length > 0);
    case "quantity": return !(v && typeof v === "object" && Object.values(v as Record<string, number>).some((n) => Number(n) > 0));
    case "text": return !(typeof v === "string" && v.trim().length > 0);
    case "number": return v === null || v === undefined || v === "";
    default: return true;
  }
}

function Check({ on }: { on: boolean }) {
  return (
    <span className={styles.finCheck} data-on={on || undefined} aria-hidden style={{ cursor: "inherit" }}>
      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3.5} strokeLinecap="round" strokeLinejoin="round"><path d="M5 13l4 4L19 7" /></svg>
    </span>
  );
}

/**
 * Member-facing options (#218). Renders every type (checkbox / select / multi-select /
 * quantity / text / number), grouped by section, respecting dependencies (a dependent
 * option is hidden until its parent is selected). Selecting enrolls into the option's
 * bundled contests server-side. "Your total" is the derived charge preview.
 */
export default function OptionsModule({
  eventId, options, groups, initialSelections, tripCostCents, onRoster,
}: {
  eventId: string;
  options: MemberOption[];
  groups: MemberGroup[];
  initialSelections: Record<string, unknown>;
  tripCostCents: number;
  onRoster: boolean;
}) {
  const [sel, setSel] = useState<Record<string, unknown>>(initialSelections);
  const [busyId, setBusyId] = useState<string | null>(null);

  const selectedOf = (o: MemberOption) => !isEmptyValue(o.option_type, sel[o.id]);

  async function save(o: MemberOption, value: unknown) {
    const prev = sel[o.id];
    const empty = isEmptyValue(o.option_type, value);
    setSel((s) => { const n = { ...s }; if (empty) delete n[o.id]; else n[o.id] = value; return n; });
    setBusyId(o.id);
    try {
      const url = `/api/v2/events/${eventId}/options/${o.id}/selection`;
      const res = empty
        ? await fetch(url, { method: "DELETE" })
        : await fetch(url, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ value }) });
      if (!res.ok) throw new Error();
    } catch {
      setSel((s) => { const n = { ...s }; if (prev === undefined) delete n[o.id]; else n[o.id] = prev; return n; });
    } finally {
      setBusyId(null);
    }
  }

  // Dependency gate: hide a dependent option until its parent is selected.
  const byId = new Map(options.map((o) => [o.id, o]));
  const visible = (o: MemberOption) => {
    if (!o.depends_on_option_id) return true;
    const parent = byId.get(o.depends_on_option_id);
    return parent ? selectedOf(parent) : true;
  };

  const shown = options.filter(visible);
  const selectedTotal = shown.filter(selectedOf).reduce((s, o) => s + o.price_cents, 0);
  const total = (onRoster ? tripCostCents : 0) + selectedTotal;

  function control(o: MemberOption) {
    const v = sel[o.id];
    const busy = busyId === o.id;
    switch (o.option_type) {
      case "checkbox":
        return (
          <button type="button" className={styles.pill} data-on={v === true || undefined} disabled={busy} onClick={() => save(o, v === true ? false : true)}>
            {v === true ? "Selected" : "Select"}
          </button>
        );
      case "select":
        return (
          <div className={styles.pillRow}>
            {(o.choices || []).map((c) => (
              <button key={c.value} type="button" className={styles.pill} data-on={v === c.value || undefined} disabled={busy}
                onClick={() => save(o, v === c.value ? "" : c.value)}>{c.label}</button>
            ))}
          </div>
        );
      case "multi_select": {
        const arr = Array.isArray(v) ? (v as string[]) : [];
        return (
          <div className={styles.pillRow}>
            {(o.choices || []).map((c) => {
              const on = arr.includes(c.value);
              return (
                <button key={c.value} type="button" className={styles.pill} data-on={on || undefined} disabled={busy}
                  onClick={() => save(o, on ? arr.filter((x) => x !== c.value) : [...arr, c.value])}>{c.label}</button>
              );
            })}
          </div>
        );
      }
      case "quantity": {
        const obj = (v && typeof v === "object" ? (v as Record<string, number>) : {});
        const sum = Object.values(obj).reduce((s, n) => s + Number(n || 0), 0);
        const atMax = o.max_total != null && sum >= o.max_total;
        return (
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {(o.choices || []).map((c) => {
              const qty = Number(obj[c.value] || 0);
              return (
                <div key={c.value} style={{ display: "flex", alignItems: "center", gap: 10 }}>
                  <span style={{ flex: 1 }}>{c.label}</span>
                  <button type="button" className={styles.stepBtn} data-kind="minor" disabled={busy || qty <= 0} onClick={() => save(o, { ...obj, [c.value]: qty - 1 })} aria-label="Less"><span className={styles.stepGlyph}>−</span></button>
                  <span className={styles.teamStepperVal} style={{ minWidth: 20, textAlign: "center" }}>{qty}</span>
                  <button type="button" className={styles.stepBtn} data-kind="minor" disabled={busy || atMax} onClick={() => save(o, { ...obj, [c.value]: qty + 1 })} aria-label="More"><span className={styles.stepGlyph}>+</span></button>
                </div>
              );
            })}
            {o.max_total != null && <p className={styles.roundFormHint}>Up to {o.max_total} total.</p>}
          </div>
        );
      }
      case "text":
        return (
          <input className={styles.input} defaultValue={typeof v === "string" ? v : ""} disabled={busy} placeholder="Your answer"
            onBlur={(e) => { const t = e.target.value; if (t !== (typeof v === "string" ? v : "")) save(o, t); }} />
        );
      case "number":
        return (
          <input className={styles.input} type="number" defaultValue={typeof v === "number" ? String(v) : ""} disabled={busy} placeholder="0"
            onBlur={(e) => { const n = e.target.value === "" ? "" : Number(e.target.value); if (n !== v) save(o, n); }} />
        );
      default:
        return null;
    }
  }

  function optionItem(o: MemberOption) {
    return (
      <div key={o.id} className={styles.optItem}>
        <div className={styles.optItemHead}>
          {o.icon && <span aria-hidden style={{ fontSize: "1.1rem" }}>{o.icon}</span>}
          <div className={styles.optMain}>
            <span className={styles.optName}>{o.name}{o.is_required ? " *" : ""}</span>
            {o.description && <span className={styles.optSub}>{o.description}</span>}
          </div>
          <span className={styles.optPrice}>{o.price_cents ? dollars(o.price_cents) : "Free"}</span>
        </div>
        <div className={styles.optItemControl}>{control(o)}</div>
      </div>
    );
  }

  const ungrouped = shown.filter((o) => !o.group_id || !groups.some((g) => g.id === o.group_id));

  return (
    <div className={styles.module}>
      <div className={styles.moduleHead}><span className={styles.sectionLabel}>Options</span></div>
      <div className={styles.optCard}>
        {onRoster && tripCostCents > 0 && (
          <div className={styles.optItem}>
            <div className={styles.optItemHead}>
              <Check on />
              <div className={styles.optMain}>
                <span className={styles.optName}>Trip Cost</span>
                <span className={styles.optSub}>Included because you&apos;re attending</span>
              </div>
              <span className={styles.optPrice}>{dollars(tripCostCents)}</span>
            </div>
          </div>
        )}

        {groups.map((g) => {
          const list = shown.filter((o) => o.group_id === g.id);
          if (list.length === 0) return null;
          return (
            <div key={g.id}>
              <p className={styles.optGroupLabel}>{g.icon ? `${g.icon} ` : ""}{g.name}</p>
              {list.map(optionItem)}
            </div>
          );
        })}

        {ungrouped.length > 0 && (
          <div>
            {groups.length > 0 && <p className={styles.optGroupLabel}>More</p>}
            {ungrouped.map(optionItem)}
          </div>
        )}

        <div className={styles.optTotalRow}>
          <span>Your total</span>
          <strong>{dollars(total)}</strong>
        </div>
      </div>
    </div>
  );
}

input.old_string:
/**
 * All-or-nothing: selecting an option enrolls the member into every contest it bundles;
 * deselecting removes them from all of them (#216). Idempotent. Options are the only
 * enrollment path for opt-in contests, so removal is safe (no cross-option sharing).
 */
export async function syncOptionContestEnrollment(
  admin: SupabaseClient,
  optionId: string,
  userId: string,
  selected: boolean,
): Promise<void> {
  const contestIds = await optionContestIds(admin, optionId);
  if (contestIds.length === 0) return;
  if (selected) {
    const rows = contestIds.map((contest_id) => ({ contest_id, user_id: userId }));
    await admin.from("v2_contest_participants").upsert(rows, { onConflict: "contest_id,user_id", ignoreDuplicates: true });
  } else {
    await admin.from("v2_contest_participants").delete().eq("user_id", userId).in("contest_id", contestIds);
  }
}

input.new_string:
/** True when a selection value means "nothing selected" for its type. */
export function optionValueIsEmpty(type: OptionType, v: unknown): boolean {
  switch (type) {
    case "checkbox": return v !== true;
    case "select": return !(typeof v === "string" && v.length > 0);
    case "multi_select": return !(Array.isArray(v) && v.length > 0);
    case "quantity": return !(v && typeof v === "object" && Object.values(v as Record<string, number>).some((n) => Number(n) > 0));
    case "text": return !(typeof v === "string" && v.trim().length > 0);
    case "number": return v === null || v === undefined || v === "";
    default: return true;
  }
}

/** The choice values a selection activates (empty for non-choice types). */
export function selectedChoiceValues(type: OptionType, v: unknown): Set<string> {
  if (type === "select" && typeof v === "string") return new Set([v]);
  if (type === "multi_select" && Array.isArray(v)) return new Set(v as string[]);
  if (type === "quantity" && v && typeof v === "object") {
    return new Set(Object.entries(v as Record<string, number>).filter(([, n]) => Number(n) > 0).map(([k]) => k));
  }
  return new Set();
}

/**
 * Enroll a member into the contests their option SELECTION funds (#218 phase B). A
 * contest's funding cost_item applies when it has no choice link (whole-option) OR a
 * choice link matching the member's selection. Non-applicable option contests are
 * removed. An empty value removes the member from every contest the option bundles.
 * Idempotent. Options are the only enrollment path for opt-in contests, so removal is safe.
 */
export async function syncOptionContestEnrollment(
  admin: SupabaseClient,
  optionId: string,
  userId: string,
  value: unknown,
): Promise<void> {
  const { data: opt } = await admin.from("v2_options").select("option_type").eq("id", optionId).maybeSingle();
  const type = (opt?.option_type as OptionType) || "checkbox";

  // All cost_items funding this option that point at a contest/side game.
  const { data: items } = await admin
    .from("v2_cost_items").select("id, source_id, source_type").eq("linked_option_id", optionId).in("source_type", ["contest", "side_game"]);
  const costItems = (items || []).filter((i) => i.source_id);
  if (costItems.length === 0) return;

  const allContestIds = [...new Set(costItems.map((i) => i.source_id as string))];
  const empty = optionValueIsEmpty(type, value);
  if (empty) {
    await admin.from("v2_contest_participants").delete().eq("user_id", userId).in("contest_id", allContestIds);
    return;
  }

  // Which cost_items apply to this selection (no choice link, or a matching one)?
  const { data: links } = await admin
    .from("v2_cost_item_option_choices").select("cost_item_id, choice_value").in("cost_item_id", costItems.map((i) => i.id as string));
  const choiceLinks = new Map<string, string[]>();
  for (const l of links || []) (choiceLinks.get(l.cost_item_id as string) || choiceLinks.set(l.cost_item_id as string, []).get(l.cost_item_id as string)!).push(l.choice_value as string);

  const chosen = selectedChoiceValues(type, value);
  const applies = (itemId: string) => {
    const cv = choiceLinks.get(itemId);
    return !cv || cv.length === 0 || cv.some((v) => chosen.has(v));
  };
  const enrollIds = [...new Set(costItems.filter((i) => applies(i.id as string)).map((i) => i.source_id as string))];
  const removeIds = allContestIds.filter((id) => !enrollIds.includes(id));

  if (enrollIds.length) {
    await admin.from("v2_contest_participants").upsert(enrollIds.map((contest_id) => ({ contest_id, user_id: userId })), { onConflict: "contest_id,user_id", ignoreDuplicates: true });
  }
  if (removeIds.length) {
    await admin.from("v2_contest_participants").delete().eq("user_id", userId).in("contest_id", removeIds);
  }
}

export interface OptionPriceInfo {
  whole: number; // cost_items with no choice link (applies whenever selected)
  byChoice: Record<string, number>; // per-choice-value cost
}

/** Per-option price breakdown: whole-option cost + per-choice costs (phase B). */
export async function loadOptionChoicePrices(admin: SupabaseClient, optionIds: string[]): Promise<Map<string, OptionPriceInfo>> {
  const out = new Map<string, OptionPriceInfo>();
  if (!optionIds.length) return out;
  for (const id of optionIds) out.set(id, { whole: 0, byChoice: {} });

  const { data: items } = await admin
    .from("v2_cost_items").select("id, amount_cents, linked_option_id").in("linked_option_id", optionIds);
  const costItems = items || [];
  const { data: links } = costItems.length
    ? await admin.from("v2_cost_item_option_choices").select("cost_item_id, choice_value").in("cost_item_id", costItems.map((i) => i.id as string))
    : { data: [] as { cost_item_id: string; choice_value: string }[] };
  const linksByItem = new Map<string, string[]>();
  for (const l of links || []) (linksByItem.get(l.cost_item_id as string) || linksByItem.set(l.cost_item_id as string, []).get(l.cost_item_id as string)!).push(l.choice_value as string);

  for (const it of costItems) {
    const oid = it.linked_option_id as string;
    const info = out.get(oid)!;
    const amt = (it.amount_cents as number) || 0;
    const choiceVals = linksByItem.get(it.id as string);
    if (!choiceVals || choiceVals.length === 0) info.whole += amt;
    else for (const cv of choiceVals) info.byChoice[cv] = (info.byChoice[cv] || 0) + amt;
  }
  return out;
}

/** The cents a given selection value costs, using an option's price breakdown. */
export function priceForValue(type: OptionType, value: unknown, info: OptionPriceInfo): number {
  if (optionValueIsEmpty(type, value)) return 0;
  if (type === "quantity" && value && typeof value === "object") {
    const q = value as Record<string, number>;
    return info.whole + Object.entries(q).reduce((s, [cv, n]) => s + (info.byChoice[cv] || 0) * Number(n || 0), 0);
  }
  const chosen = selectedChoiceValues(type, value);
  if (chosen.size === 0) return info.whole; // checkbox
  return info.whole + [...chosen].reduce((s, cv) => s + (info.byChoice[cv] || 0), 0);
}

