"use client";

import styles from "@/app/new/new.module.css";
import type { OptionType, OptionChoice, OptionPriceInfo } from "@/lib/v2/options";

export interface MemberOption {
  id: string;
  name: string;
  description: string | null;
  option_type: OptionType;
  choices: OptionChoice[] | null;
  is_required: boolean;
  max_total: number | null;
  icon: string | null;
  group_id: string | null;
  depends_on_option_id: string | null;
  price_info: OptionPriceInfo;
}
export interface MemberGroup { id: string; name: string; icon: string | null }

export function dollars(cents: number): string {
  return `$${(cents / 100).toLocaleString("en-US", { minimumFractionDigits: cents % 100 === 0 ? 0 : 2, maximumFractionDigits: 2 })}`;
}

export function isEmptyValue(type: OptionType, v: unknown): boolean {
  switch (type) {
    case "checkbox": return v !== true;
    case "select": return !(typeof v === "string" && v.length > 0);
    case "multi_select": return !(Array.isArray(v) && v.length > 0);
    case "quantity": return !(v && typeof v === "object" && Object.values(v as Record<string, number>).some((n) => Number(n) > 0));
    case "text": return !(typeof v === "string" && v.trim().length > 0);
    case "number": return v === null || v === undefined || v === "";
    default: return true;
  }
}

/** The per-type control for one option. Decoupled from persistence: calls onChange
 *  with the new value; the parent saves. `disabled` locks it (closed / read-only). */
export function OptionControl({ option: o, value: v, disabled, onChange }: {
  option: MemberOption; value: unknown; disabled: boolean; onChange: (v: unknown) => void;
}) {
  switch (o.option_type) {
    case "checkbox":
      return (
        <button type="button" className={styles.pill} data-on={v === true || undefined} disabled={disabled} onClick={() => onChange(v === true ? false : true)}>
          {v === true ? "Selected" : "Select"}
        </button>
      );
    case "select":
      return (
        <div className={styles.pillRow}>
          {(o.choices || []).map((c) => {
            const p = o.price_info.byChoice[c.value] || 0;
            return (
              <button key={c.value} type="button" className={styles.pill} data-on={v === c.value || undefined} disabled={disabled}
                onClick={() => onChange(v === c.value ? "" : c.value)}>{c.label}{p ? ` ${dollars(p)}` : ""}</button>
            );
          })}
        </div>
      );
    case "multi_select": {
      const arr = Array.isArray(v) ? (v as string[]) : [];
      return (
        <div className={styles.pillRow}>
          {(o.choices || []).map((c) => {
            const on = arr.includes(c.value);
            const p = o.price_info.byChoice[c.value] || 0;
            return (
              <button key={c.value} type="button" className={styles.pill} data-on={on || undefined} disabled={disabled}
                onClick={() => onChange(on ? arr.filter((x) => x !== c.value) : [...arr, c.value])}>{c.label}{p ? ` ${dollars(p)}` : ""}</button>
            );
          })}
        </div>
      );
    }
    case "quantity": {
      const obj = (v && typeof v === "object" ? (v as Record<string, number>) : {});
      const sum = Object.values(obj).reduce((s, n) => s + Number(n || 0), 0);
      const atMax = o.max_total != null && sum >= o.max_total;
      return (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {(o.choices || []).map((c) => {
            const qty = Number(obj[c.value] || 0);
            const per = o.price_info.byChoice[c.value] || 0;
            return (
              <div key={c.value} style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <span style={{ flex: 1 }}>{c.label}{per ? ` (${dollars(per)} each)` : ""}</span>
                <button type="button" className={styles.stepBtn} data-kind="minor" disabled={disabled || qty <= 0} onClick={() => onChange({ ...obj, [c.value]: qty - 1 })} aria-label="Less"><span className={styles.stepGlyph}>−</span></button>
                <span className={styles.teamStepperVal} style={{ minWidth: 20, textAlign: "center" }}>{qty}</span>
                <button type="button" className={styles.stepBtn} data-kind="minor" disabled={disabled || atMax} onClick={() => onChange({ ...obj, [c.value]: qty + 1 })} aria-label="More"><span className={styles.stepGlyph}>+</span></button>
              </div>
            );
          })}
          {o.max_total != null && <p className={styles.roundFormHint}>Up to {o.max_total} total.</p>}
        </div>
      );
    }
    case "text":
      return (
        <input className={styles.input} defaultValue={typeof v === "string" ? v : ""} disabled={disabled} placeholder="Your answer"
          onBlur={(e) => { const t = e.target.value; if (t !== (typeof v === "string" ? v : "")) onChange(t); }} />
      );
    case "number":
      return (
        <input className={styles.input} type="number" defaultValue={typeof v === "number" ? String(v) : ""} disabled={disabled} placeholder="0"
          onBlur={(e) => { const n = e.target.value === "" ? "" : Number(e.target.value); if (n !== v) onChange(n); }} />
      );
    default:
      return null;
  }
}

