65	export async function PUT(
66	  request: Request,
67	  { params }: { params: Promise<{ id: string; eventId: string }> },
68	) {
69	  const { id, eventId } = await params;
70	  const { userId } = await v2GetUser(request);
71	  if (!userId) return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
72	  const admin = v2AdminClient();
73	  if (!(await isOrgAdmin(admin, userId, id))) {
74	    return NextResponse.json({ error: "Not allowed" }, { status: 403 });
75	  }
76	
77	  let body: { features?: FeatureInput[] };
78	  try {
79	    body = await request.json();
80	  } catch {
81	    return NextResponse.json({ error: "Invalid body" }, { status: 400 });
82	  }
83	  const inputs = Array.isArray(body.features) ? body.features : [];
84	
85	  // Validate keys: must be catalogued, event-scoped, built ('available'), and not
86	  // an always-on utility.
87	  const now = new Date().toISOString();
88	  const rows = [] as Record<string, unknown>[];
89	  let pinnedCount = 0;
90	  for (const inp of inputs) {
91	    const def = FEATURE_BY_KEY[inp.feature_key];
92	    if (!def) return NextResponse.json({ error: `Unknown feature: ${inp.feature_key}` }, { status: 400 });
93	    if (def.alwaysOn) return NextResponse.json({ error: `${def.label} is always on` }, { status: 400 });
94	    if (def.scope !== "event") {
95	      return NextResponse.json({ error: `${def.label} is configured in Group features` }, { status: 400 });
96	    }
97	    if (def.status !== "available") {
98	      return NextResponse.json({ error: `${def.label} isn't available yet` }, { status: 400 });
99	    }
100	    const visibility = VISIBILITIES.includes(inp.visibility || "") ? inp.visibility! : "off";
101	    const on = visibility !== "off";
102	    const pinned = on && !!inp.pinned;
103	    if (pinned) pinnedCount += 1;
104	    const availability = inp.availability === "window" ? "window" : "always";
105	    rows.push({
106	      org_id: id,
107	      event_id: eventId,
108	      feature_key: inp.feature_key,
109	      visibility,
110	      pinned,
111	      nav_order: Number.isFinite(inp.nav_order) ? Math.trunc(inp.nav_order as number) : 0,
112	      label_override: inp.label_override?.trim() || null,
113	      // Spectator-public only makes sense when the feature is on for everyone.
114	      public: visibility === "everyone" && !!inp.public,
115	      availability,
116	      available_from: availability === "window" ? inp.available_from || null : null,
117	      available_until: availability === "window" ? inp.available_until || null : null,
118	      updated_at: now,
119	      updated_by: userId,
120	    });
121	  }
122	
123	  if (pinnedCount > MAX_PINNED) {
124	    return NextResponse.json(
125	      { error: `You can pin at most ${MAX_PINNED} features to the bottom bar.` },
126	      { status: 400 },
127	    );
128	  }
129	
130	  // Replace the event-scoped rows for exactly the keys we were given (a partial
131	  // unique index can't be inferred by PostgREST upsert, so delete-then-insert).
132	  if (rows.length) {
133	    const keys = rows.map((r) => r.feature_key as string);
134	    const { error: delErr } = await admin
135	      .from("v2_event_features")
136	      .delete()
137	      .eq("org_id", id)
138	      .eq("event_id", eventId)
139	      .in("feature_key", keys);
140	    if (delErr) return NextResponse.json({ error: delErr.message }, { status: 500 });
141	    const { error: insErr } = await admin.from("v2_event_features").insert(rows);
142	    if (insErr) return NextResponse.json({ error: insErr.message }, { status: 500 });
143	  }
144	
145	  const fresh = await loadRows(admin, id, eventId);
146	  return NextResponse.json({ features: resolveFeatures(fresh, eventId) });
