134	export async function loadOptionChoicePrices(admin: SupabaseClient, optionIds: string[]): Promise<Map<string, OptionPriceInfo>> {
135	  const out = new Map<string, OptionPriceInfo>();
136	  if (!optionIds.length) return out;
137	  for (const id of optionIds) out.set(id, { whole: 0, byChoice: {} });
138	
139	  const { data: items } = await admin
140	    .from("v2_cost_items").select("id, amount_cents, linked_option_id").in("linked_option_id", optionIds);
141	  const costItems = items || [];
142	  const { data: links } = costItems.length
143	    ? await admin.from("v2_cost_item_option_choices").select("cost_item_id, choice_value").in("cost_item_id", costItems.map((i) => i.id as string))
144	    : { data: [] as { cost_item_id: string; choice_value: string }[] };
145	  const linksByItem = new Map<string, string[]>();
146	  for (const l of links || []) (linksByItem.get(l.cost_item_id as string) || linksByItem.set(l.cost_item_id as string, []).get(l.cost_item_id as string)!).push(l.choice_value as string);
147	
148	  for (const it of costItems) {
149	    const oid = it.linked_option_id as string;
150	    const info = out.get(oid)!;
151	    const amt = (it.amount_cents as number) || 0;
152	    const choiceVals = linksByItem.get(it.id as string);
153	    if (!choiceVals || choiceVals.length === 0) info.whole += amt;
154	    else for (const cv of choiceVals) info.byChoice[cv] = (info.byChoice[cv] || 0) + amt;
155	  }
156	  return out;
157	}
