160	export function priceForValue(type: OptionType, value: unknown, info: OptionPriceInfo): number {
161	  if (optionValueIsEmpty(type, value)) return 0;
162	  if (type === "quantity" && value && typeof value === "object") {
163	    const q = value as Record<string, number>;
164	    return info.whole + Object.entries(q).reduce((s, [cv, n]) => s + (info.byChoice[cv] || 0) * Number(n || 0), 0);
165	  }
166	  const chosen = selectedChoiceValues(type, value);
167	  if (chosen.size === 0) return info.whole; // checkbox
168	  return info.whole + [...chosen].reduce((s, cv) => s + (info.byChoice[cv] || 0), 0);
