function costSection(o: OptionData) {
  const hasChoices = typeHasChoices(o.option_type) && !!o.choices?.length;

  // Choice options: a persistent matrix. Every assignable cost stays in the list;
  // tap the choices each cost applies to. One cost can fund several choices (e.g. a
  // Monday hotel night on all three "arrive Monday" choices). Nothing disappears.
  if (hasChoices) {
    const allValues = (o.choices || []).map((c) => c.value);
    const candidates = [...o.items, ...available];
    const groups = groupItems(candidates);
    return (
      <div style={{ marginTop: 16 }}>
        <p className={styles.sectionLabel}>Costs by choice</p>
        <p className={styles.roundFormHint} style={{ marginTop: -2, marginBottom: 8 }}>
          Tap the choices each cost applies to. A cost can apply to several, or all. Costs stay listed whether or not they&apos;re used.
        </p>
        {candidates.length === 0 ? (
          <p className={styles.dnsHint} style={{ marginTop: 4 }}>No costs available. Create a contest with a buy-in, or add a manual cost on the Financials screen first.</p>
        ) : (
          <div className={styles.finGroups}>
            {groups.map((g) => (
              <div key={g.key} className={styles.finGroup}>
                <p className={styles.finGroupHead}>{g.label}</p>
                <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                  {g.list.map((it) => {
                    const on = new Set(effectiveChoices(o, it));
                    const allOn = allValues.length > 0 && allValues.every((v) => on.has(v));
                    return (
                      <div key={it.id} className={styles.costChoiceRow} data-active={on.size > 0 || undefined}>
                        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                          <span className={styles.finRowName} style={{ flex: 1, minWidth: 0 }}>{it.name}</span>
                          <span className={styles.finRowAmount}>{dollars(it.amount_cents)}</span>
                        </div>
                        <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginTop: 8 }}>
                          {(o.choices || []).map((c) => (
                            <button key={c.value} type="button" className={styles.pill} data-on={on.has(c.value) || undefined} disabled={busy}
                              onClick={() => toggleItemChoice(o, it, c.value)}>{c.label}</button>
                          ))}
                          <button type="button" className={styles.createBtnGhost} disabled={busy}
                            onClick={() => setAllItemChoices(o, it, !allOn)}>{allOn ? "Clear" : "All"}</button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            ))}
          </div>
        )}
        <div style={{ marginTop: 12 }}>
          <button type="button" className={styles.deleteBtn} onClick={() => setConfirmDel(o)} disabled={busy}>Delete option</button>
        </div>
      </div>
    );
  }

  // Non-choice options: a plain bundle (each cost is in or out).
  return (
    <div style={{ marginTop: 16 }}>
      <p className={styles.sectionLabel}>Bundled costs</p>
      {o.items.length === 0 ? (
        <p className={styles.dnsHint} style={{ marginTop: 4 }}>No costs bundled. A $0 option is a free opt-in.</p>
      ) : (
        <div className={styles.memberList} style={{ marginTop: 4 }}>
          {o.items.map((it) => (
            <div key={it.id} className={styles.finRow}>
              <div className={styles.finRowMain} style={{ minWidth: 0 }}>
                <span className={styles.finRowName}>{it.name}</span>
              </div>
              <span className={styles.finRowAmount}>{dollars(it.amount_cents)}</span>
              <button type="button" className={styles.removeBtn} onClick={() => unlinkItem(o, it)} disabled={busy} style={{ marginLeft: 8 }}>Remove</button>
            </div>
          ))}
        </div>
      )}
      <div style={{ display: "flex", gap: 8, marginTop: 10, flexWrap: "wrap" }}>
        <button type="button" className={styles.createBtnGhost} onClick={() => setAddingTo(o)} disabled={available.length === 0}>Add cost{available.length === 0 ? " (none free)" : ""}</button>
        <button type="button" className={styles.deleteBtn} onClick={() => setConfirmDel(o)} disabled={busy}>Delete option</button>
      </div>
    </div>
  );
}

