/* Admin balances grid (#214). */
.balGrid {
  border: 1px solid var(--line);
  border-radius: 12px;
  overflow: hidden;
}
.balHead,
.balRow,
.balTotals {
  display: grid;
  grid-template-columns: 1fr auto auto auto;
  gap: 12px;
  align-items: center;
  padding: 10px 12px;
}
.balHead {
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--ink-soft);
  background: color-mix(in srgb, var(--ink) 3%, var(--card));
  border-bottom: 1px solid var(--line);
}
.balHead span:not(:first-child),
.balRow .balNum,
.balTotals .balNum { text-align: right; }
.balRow {
  width: 100%;
  border: none;
  border-bottom: 1px solid var(--line);
  background: var(--card);
  cursor: pointer;
  text-align: left;
  font: inherit;
}
.balRow:last-of-type { border-bottom: none; }
.balRow:hover { background: color-mix(in srgb, var(--brand) 5%, var(--card)); }
.balName { font-weight: 600; color: var(--ink); min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.balNum { font-variant-numeric: tabular-nums; color: var(--ink); white-space: nowrap; }
.balNum[data-paid] { color: #15803d; }
.balNum[data-state="owes"] { color: var(--warn, #c2410c); font-weight: 700; }
.balNum[data-state="credit"] { color: #15803d; font-weight: 700; }
.balNum[data-state="settled"] { color: var(--ink-soft); }
.balTotals {
  font-weight: 800;
  background: color-mix(in srgb, var(--ink) 3%, var(--card));
  border-top: 1px solid var(--line);
}
.balSummary {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}
.balSummary > div {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 10px 12px;
  border-radius: 10px;
  background: color-mix(in srgb, var(--ink) 3%, var(--card));
}
.balSummaryLabel { font-size: 0.72rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em; color: var(--ink-soft); }
.balSummaryVal { font-size: 1.1rem; font-weight: 800; color: var(--ink); font-variant-numeric: tabular-nums; }
.balSummaryVal[data-state="owes"] { color: var(--warn, #c2410c); }
.balSummaryVal[data-state="credit"] { color: #15803d; }

