26	function isEmptyValue(type: OptionType, v: unknown): boolean {
27	  switch (type) {
28	    case "checkbox": return v !== true;
29	    case "select": return !(typeof v === "string" && v.length > 0);
30	    case "multi_select": return !(Array.isArray(v) && v.length > 0);
