54	}: {
55	  eventId: string;
56	  options: MemberOption[];
57	  groups: MemberGroup[];
58	  initialSelections: Record<string, unknown>;
59	  tripCostCents: number;
60	  tripCostOptionId: string | null;
61	  onRoster: boolean;
62	  optionsOpen: boolean;
63	}) {
64	  const [sel, setSel] = useState<Record<string, unknown>>(initialSelections);
65	  const [busyId, setBusyId] = useState<string | null>(null);
66	
67	  const selectedOf = (o: MemberOption) => !isEmptyValue(o.option_type, sel[o.id]);
68	
69	  async function save(o: MemberOption, value: unknown) {
70	    const prev = sel[o.id];
71	    const empty = isEmptyValue(o.option_type, value);
72	    setSel((s) => { const n = { ...s }; if (empty) delete n[o.id]; else n[o.id] = value; return n; });
73	    setBusyId(o.id);
74	    try {
75	      const url = `/api/v2/events/${eventId}/options/${o.id}/selection`;
76	      const res = empty
