90	  const byId = new Map(options.map((o) => [o.id, o]));
91	  const visible = (o: MemberOption): boolean => {
92	    if (!o.depends_on_option_id) return true;
93	    if (tripCostOptionId && o.depends_on_option_id === tripCostOptionId) return onRoster;
94	    const parent = byId.get(o.depends_on_option_id);
95	    return parent ? selectedOf(parent) : true;
96	  };
97

