101	  const headPrice = (o: MemberOption) => {
102	    if (o.option_type === "checkbox") return o.price_info.whole ? dollars(o.price_info.whole) : "Free";
103	    if (o.option_type === "text" || o.option_type === "number") return "";
104	    return ""; // choice types show price per choice below
105	  };
