import { useState } from "react";
import styles from "@/app/new/new.module.css";
import { priceForValue, type OptionType, type OptionChoice, type OptionPriceInfo } from "@/lib/v2/options";

export interface MemberOption {
  id: string;
  name: string;
  description: string | null;
  option_type: OptionType;
  choices: OptionChoice[] | null;
  is_required: boolean;
  max_total: number | null;
  icon: string | null;
  group_id: string | null;
  depends_on_option_id: string | null;
  price_info: OptionPriceInfo;
}
export interface MemberGroup { id: string; name: string; icon: string | null }

function dollars(cents: number): string {
  return `$${(cents / 100).toLocaleString("en-US", { minimumFractionDigits: cents % 100 === 0 ? 0 : 2, maximumFractionDigits: 2 })}`;
}

function isEmptyValue(type: OptionType, v: unknown): boolean {
  switch (type) {
    case "checkbox": return v !== true;
    case "select": return !(typeof v === "string" && v.length > 0);
    case "multi_select": return !(Array.isArray(v) && v.length > 0);
    case "quantity": return !(v && typeof v === "object" && Object.values(v as Record<string, number>).some((n) => Number(n) > 0));
    case "text": return !(typeof v === "string" && v.trim().length > 0);
    case "number": return v === null || v === undefined || v === "";
    default: return true;
  }
}

