"use client";

import { useCallback, useEffect, useState } from "react";
import styles from "@/app/new/new.module.css";
import ConfirmModal from "@/app/new/_components/ConfirmModal";
import { FBS_TEAMS } from "@/lib/data/fbs-teams";
/* eslint-disable @next/next/no-img-element */

interface Game {
  id: string;
  away_team: string; home_team: string;
  away_logo_url: string | null; home_logo_url: string | null;
  spread: number | null; favorite: "away" | "home" | null;
  game_time: string | null; tv_channel: string | null;
  is_tiebreaker: boolean;
  away_score: number | null; home_score: number | null;
  sort_order: number;
}

const BY_CONF = (() => {
  const m = new Map<string, typeof FBS_TEAMS>();
  for (const t of FBS_TEAMS) (m.get(t.conference) || m.set(t.conference, []).get(t.conference)!).push(t);
  return [...m.entries()].sort((a, b) => a[0].localeCompare(b[0]));
})();

function TeamSelect({ value, onChange, placeholder }: { value: string; onChange: (v: string) => void; placeholder: string }) {
  return (
    <select className={styles.selectInput} value={value} onChange={(e) => onChange(e.target.value)}>
      <option value="">{placeholder}</option>
      {BY_CONF.map(([conf, teams]) => (
        <optgroup key={conf} label={conf}>
          {teams.map((t) => <option key={t.shortName} value={t.shortName}>{t.shortName}</option>)}
        </optgroup>
      ))}
    </select>
  );
}

// datetime-local <-> ISO helpers.
const toLocal = (iso: string | null) => {
  if (!iso) return "";
  const d = new Date(iso); const p = (n: number) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`;
};

export default function PickemAdmin({ slug, orgId, eventId, contestId, initialStatus }: {
  slug: string; orgId: string; eventId: string; contestId: string; initialStatus: string;
}) {
  void slug;
  const base = `/api/v2/orgs/${orgId}/events/${eventId}/contests/${contestId}`;
  const [games, setGames] = useState<Game[]>([]);
  const [status, setStatus] = useState(initialStatus);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [confirmDel, setConfirmDel] = useState<string | null>(null);

  // Add-game form
  const [away, setAway] = useState("");
  const [home, setHome] = useState("");
  const [favorite, setFavorite] = useState<"away" | "home">("home");
  const [spread, setSpread] = useState("");
  const [gameTime, setGameTime] = useState("");
  const [tv, setTv] = useState("");
  const [isTb, setIsTb] = useState(false);

  const load = useCallback(async () => {
    const res = await fetch(`${base}/pickem`);
    if (res.ok) setGames((await res.json()).games || []);
  }, [base]);
  useEffect(() => { load(); }, [load]);

  async function addGame(e: React.FormEvent) {
    e.preventDefault();
    if (busy) return;
    if (!away || !home) { setError("Pick both teams"); return; }
    setBusy(true); setError(null);
    try {
      const res = await fetch(`${base}/pickem`, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          away_team: away, home_team: home, favorite,
          spread: spread.trim() ? Number(spread) : undefined,
          game_time: gameTime ? new Date(gameTime).toISOString() : null,
          tv_channel: tv.trim() || null, is_tiebreaker: isTb,
        }),
      });
      if (!res.ok) { setError((await res.json().catch(() => ({}))).error || "Could not add"); return; }
      setAway(""); setHome(""); setSpread(""); setGameTime(""); setTv(""); setIsTb(false);
      await load();
    } finally { setBusy(false); }
  }

  async function patchGame(gameId: string, patch: Record<string, unknown>) {
    setBusy(true); setError(null);
    try {
      const res = await fetch(`${base}/pickem`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ gameId, ...patch }) });
      if (!res.ok) { setError((await res.json().catch(() => ({}))).error || "Could not save"); return; }
      await load();
    } finally { setBusy(false); }
  }

  function saveResult(g: Game, awayScore: string, homeScore: string) {
    const a = awayScore.trim() === "" ? null : Math.max(0, Math.round(Number(awayScore)));
    const h = homeScore.trim() === "" ? null : Math.max(0, Math.round(Number(homeScore)));
    const winning_team = a != null && h != null ? (h > a ? "home" : a > h ? "away" : null) : null;
    patchGame(g.id, { away_score: a, home_score: h, winning_team });
  }

  async function del(gameId: string) {
    setBusy(true); setError(null);
    try {
      const res = await fetch(`${base}/pickem?gameId=${gameId}`, { method: "DELETE" });
      if (!res.ok) { setError("Could not delete"); return; }
      setConfirmDel(null);
      await load();
    } finally { setBusy(false); }
  }

  async function toggleOpen() {
    const next = status === "active" ? "draft" : "active";
    setBusy(true); setError(null);
    const prev = status;
    setStatus(next);
    try {
      const res = await fetch(base, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ status: next }) });
      if (!res.ok) throw new Error();
    } catch { setStatus(prev); setError("Could not change status"); }
    finally { setBusy(false); }
  }

  return (
    <div style={{ marginTop: 8 }}>
      <div className={styles.cscAcc} style={{ marginBottom: 16 }}>
        <div className={styles.cscAccBody} style={{ paddingTop: 12 }}>
          <label className={styles.profileToggle} style={{ marginTop: 0 }}>
            <input type="checkbox" checked={status === "active"} onChange={toggleOpen} disabled={busy} />
            <span>Open to members {status === "active" ? "(visible, picks allowed)" : "(hidden)"}</span>
          </label>
        </div>
      </div>

      <p className={styles.sectionLabel}>Games ({games.length})</p>
      {games.length === 0 ? (
        <p className={styles.dnsHint} style={{ marginTop: 4 }}>No games yet. Add the Saturday slate below.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 8, marginTop: 4 }}>
          {games.map((g) => (
            <div key={g.id} className={styles.pickCard}>
              <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                {g.away_logo_url && <img src={g.away_logo_url} alt="" className={styles.pickLogo} />}
                <span style={{ fontWeight: 600 }}>{g.away_team}</span>
                <span className={styles.pickSpread}>{g.favorite === "away" ? `-${Math.abs(Number(g.spread ?? 0))}` : g.spread != null ? `+${Math.abs(Number(g.spread))}` : ""}</span>
                <span style={{ color: "var(--ink-soft)" }}>@</span>
                {g.home_logo_url && <img src={g.home_logo_url} alt="" className={styles.pickLogo} />}
                <span style={{ fontWeight: 600 }}>{g.home_team}</span>
                <span className={styles.pickSpread}>{g.favorite === "home" ? `-${Math.abs(Number(g.spread ?? 0))}` : g.spread != null ? `+${Math.abs(Number(g.spread))}` : ""}</span>
                <span style={{ flex: 1 }} />
                <button type="button" className={styles.removeBtn} onClick={() => patchGame(g.id, { is_tiebreaker: !g.is_tiebreaker })} disabled={busy}>{g.is_tiebreaker ? "★ TB" : "☆ TB"}</button>
                <button type="button" className={styles.removeBtn} onClick={() => setConfirmDel(g.id)} disabled={busy}>Remove</button>
              </div>
              <div className={styles.pickCardMeta} style={{ marginTop: 6, marginBottom: 0 }}>
                {g.game_time ? new Date(g.game_time).toLocaleString("en-US", { weekday: "short", hour: "numeric", minute: "2-digit" }) : "No time"}{g.tv_channel ? ` · ${g.tv_channel}` : ""}
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 6, marginTop: 8 }}>
                <span className={styles.label} style={{ marginBottom: 0 }}>Final</span>
                <input className={styles.input} inputMode="numeric" style={{ width: 56 }} defaultValue={g.away_score ?? ""} placeholder={g.away_team.slice(0, 4)}
                  onBlur={(e) => { const h = (e.currentTarget.parentElement?.querySelector("[data-home]") as HTMLInputElement | null)?.value ?? ""; saveResult(g, e.target.value, h); }} />
                <span style={{ color: "var(--ink-soft)" }}>–</span>
                <input className={styles.input} inputMode="numeric" style={{ width: 56 }} data-home defaultValue={g.home_score ?? ""} placeholder={g.home_team.slice(0, 4)}
                  onBlur={(e) => { const a = (e.currentTarget.parentElement?.querySelector("input:not([data-home])") as HTMLInputElement | null)?.value ?? ""; saveResult(g, a, e.target.value); }} />
              </div>
            </div>
          ))}
        </div>
      )}

      <form className={styles.form} onSubmit={addGame} style={{ marginTop: 18 }}>
        <p className={styles.sectionLabel} style={{ marginBottom: 6 }}>Add a game</p>
        <div className={styles.profileTwoCol}>
          <div className={styles.field}><label className={styles.label}>Away</label><TeamSelect value={away} onChange={setAway} placeholder="Away team" /></div>
          <div className={styles.field}><label className={styles.label}>Home</label><TeamSelect value={home} onChange={setHome} placeholder="Home team" /></div>
        </div>
        <div className={styles.profileTwoCol}>
          <div className={styles.field}>
            <label className={styles.label}>Favorite</label>
            <select className={styles.selectInput} value={favorite} onChange={(e) => setFavorite(e.target.value as "away" | "home")}>
              <option value="home">Home</option>
              <option value="away">Away</option>
            </select>
          </div>
          <div className={styles.field}><label className={styles.label}>Spread</label><input className={styles.input} inputMode="decimal" value={spread} onChange={(e) => setSpread(e.target.value.replace(/[^0-9.]/g, ""))} placeholder="e.g. 7" /></div>
        </div>
        <div className={styles.profileTwoCol}>
          <div className={styles.field}><label className={styles.label}>Kickoff</label><input type="datetime-local" className={styles.input} value={gameTime} onChange={(e) => setGameTime(e.target.value)} /></div>
          <div className={styles.field}><label className={styles.label}>TV <span className={styles.optional}>(optional)</span></label><input className={styles.input} value={tv} onChange={(e) => setTv(e.target.value)} placeholder="ESPN" /></div>
        </div>
        <label className={styles.profileToggle}><input type="checkbox" checked={isTb} onChange={(e) => setIsTb(e.target.checked)} /><span>Tiebreaker game (guess total points)</span></label>
        {error && <p className={styles.formError}>{error}</p>}
        <button type="submit" className={styles.createBtn} disabled={busy} style={{ opacity: busy ? 0.6 : 1 }}>{busy ? "Saving…" : "Add game"}</button>
      </form>

      <ConfirmModal open={!!confirmDel} title="Remove this game?" message="This deletes the game and everyone's picks on it." confirmLabel="Remove" destructive onConfirm={() => confirmDel && del(confirmDel)} onCancel={() => setConfirmDel(null)} />
      <p style={{ marginTop: 10 }} />
      {toLocal(null) === "" ? null : null}
    </div>
  );
}

