-- 00262_v2_pickem_payments.sql
-- Pick'em money (#209 Phase 2). Who has paid the Pick'em entry fee — a self-contained
-- side pot, separate from the trip balance. Presence of a row = paid. The entry fee
-- (cents) lives on v2_contests.config.entry_fee_cents and the payout splits on
-- v2_contests.payout_splits; pot = fee × paid count, split by %-of-pot (rounded to $5).

DROP TABLE IF EXISTS public.v2_pickem_payments CASCADE;

CREATE TABLE public.v2_pickem_payments (
  id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  contest_id UUID NOT NULL REFERENCES public.v2_contests(id) ON DELETE CASCADE,
  user_id    UUID NOT NULL REFERENCES public.v2_profiles(id) ON DELETE CASCADE,
  paid_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  paid_by    UUID REFERENCES public.v2_profiles(id) ON DELETE SET NULL,
  UNIQUE (contest_id, user_id)
);
CREATE INDEX idx_v2_pickem_payments_contest ON public.v2_pickem_payments(contest_id);

ALTER TABLE public.v2_pickem_payments ENABLE ROW LEVEL SECURITY;
CREATE POLICY "v2_pickem_payments_all" ON public.v2_pickem_payments FOR ALL TO authenticated USING (true) WITH CHECK (true);
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.v2_pickem_payments TO authenticated, service_role;

