import { NextResponse } from "next/server";
import { v2GetUser, v2AdminClient } from "@/lib/v2/supabase";
import { isOrgAdmin, orgNameMode } from "@/lib/v2/orgs";
import { pickName } from "@/lib/v2/profile";
import { computePickemPayouts, type PayoutSplit } from "@/lib/v2/contests/pickem";

type Params = Promise<{ id: string; eventId: string; contestId: string }>;

async function gate(request: Request, orgId: string, contestId: string) {
  const { userId } = await v2GetUser(request);
  if (!userId) return { error: NextResponse.json({ error: "Not authenticated" }, { status: 401 }) };
  const admin = v2AdminClient();
  if (!(await isOrgAdmin(admin, userId, orgId))) return { error: NextResponse.json({ error: "Admins only" }, { status: 403 }) };
  const { data: contest } = await admin.from("v2_contests").select("id, contest_type, config, payout_splits").eq("id", contestId).eq("org_id", orgId).maybeSingle();
  if (!contest || contest.contest_type !== "pickem") return { error: NextResponse.json({ error: "Not a Pick'em contest" }, { status: 404 }) };
  return { admin, userId, contest };
}

/** Payments + pot + computed payouts for the admin money panel (#209 Phase 2). */
export async function GET(request: Request, { params }: { params: Params }) {
  const { id: orgId, eventId, contestId } = await params;
  void eventId;
  const g = await gate(request, orgId, contestId);
  if ("error" in g) return g.error;

  const entryFeeCents = Number((g.contest.config as { entry_fee_cents?: number } | null)?.entry_fee_cents || 0);
  const payoutSplits = (g.contest.payout_splits as PayoutSplit[] | null) || [];

  const { data: games } = await g.admin.from("v2_pickem_games").select("id").eq("contest_id", contestId);
  const gameIds = (games || []).map((x) => x.id as string);
  const { data: picks } = gameIds.length
    ? await g.admin.from("v2_pickem_picks").select("user_id, picked_team").in("game_id", gameIds)
    : { data: [] as { user_id: string; picked_team: string | null }[] };
  const pickedCount = new Map<string, number>();
  for (const p of picks || []) if (p.picked_team) pickedCount.set(p.user_id as string, (pickedCount.get(p.user_id as string) || 0) + 1);

  const { data: pays } = await g.admin.from("v2_pickem_payments").select("user_id").eq("contest_id", contestId);
  const paid = new Set((pays || []).map((p) => p.user_id as string));

  const userIds = [...new Set([...pickedCount.keys(), ...paid])];
  const [{ data: profs }, mode] = await Promise.all([
    userIds.length ? g.admin.from("v2_profiles").select("id, display_name, first_name, last_name, avatar_url").in("id", userIds) : Promise.resolve({ data: [] as { id: string; display_name: string | null; first_name: string | null; last_name: string | null; avatar_url: string | null }[] }),
    orgNameMode(g.admin, orgId),
  ]);
  const prof = new Map((profs || []).map((p) => [p.id as string, p]));

  const participants = userIds
    .map((uid) => ({ userId: uid, name: prof.has(uid) ? pickName(prof.get(uid)!, mode) : "Member", avatarUrl: (prof.get(uid)?.avatar_url as string | null) ?? null, paid: paid.has(uid), pickedCount: pickedCount.get(uid) || 0 }))
    .sort((a, b) => a.name.localeCompare(b.name));

