  return NextResponse.json({ entryFeeCents, payoutSplits, participants, paidCount: paid.size, potCents, payouts: computePickemPayouts(potCents, payoutSplits) });
}

export async function PUT(request: Request, { params }: { params: Params }) {
  const { id: orgId, contestId } = await params;
  const g = await gate(request, orgId, contestId);
  if ("error" in g) return g.error;
  let body: { userId?: string; paid?: boolean };
  try { body = await request.json(); } catch { return NextResponse.json({ error: "Invalid body" }, { status: 400 }); }
  if (!body.userId) return NextResponse.json({ error: "userId required" }, { status: 400 });

  if (body.paid) {
    const { error } = await g.admin.from("v2_pickem_payments").upsert({ contest_id: contestId, user_id: body.userId, paid_at: new Date().toISOString(), paid_by: g.userId }, { onConflict: "contest_id,user_id" });
    if (error) return NextResponse.json({ error: error.message }, { status: 500 });
  } else {
    const { error } = await g.admin.from("v2_pickem_payments").delete().eq("contest_id", contestId).eq("user_id", body.userId);
    if (error) return NextResponse.json({ error: error.message }, { status: 500 });
  }
  return NextResponse.json({ ok: true });
}

