"use client";

import { useEffect, useState } from "react";
import styles from "@/app/new/new.module.css";

export function ordinal(n: number): string {
  const s = ["th", "st", "nd", "rd"];
  const v = n % 100;
  return `${n}${s[(v - 20) % 10] || s[v] || s[0]}`;
}

/**
 * Shared editor for a contest's pot %-splits per place (any contest). Self-contained:
 * edits locally, commits (saves) on blur / add / remove via onSave.
 */
export default function PayoutSplitsEditor({ value, onSave, disabled }: {
  value: number[];
  onSave: (next: number[]) => void;
  disabled?: boolean;
}) {
  const [splits, setSplits] = useState<number[]>(value);
  useEffect(() => { setSplits(value); }, [value]);
  const total = splits.reduce((s, n) => s + (Number(n) || 0), 0);

  return (
    <div>
      {splits.map((pct, i) => (
        <div key={i} style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
          <span style={{ width: 44, color: "var(--ink-soft)" }}>{ordinal(i + 1)}</span>
          <input className={styles.input} inputMode="numeric" style={{ width: 80 }} value={pct} disabled={disabled}
            onChange={(e) => { const v = Number(e.target.value.replace(/[^0-9]/g, "")) || 0; setSplits((s) => s.map((x, j) => (j === i ? v : x))); }}
            onBlur={() => onSave(splits)} />
          <span>%</span>
          <button type="button" className={styles.iconDelBtn} aria-label="Remove place" disabled={disabled}
            onClick={() => { const next = splits.filter((_, j) => j !== i); setSplits(next); onSave(next); }}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={1.8} strokeLinecap="round" strokeLinejoin="round" aria-hidden><path d="M3 6h18M8 6V4a1 1 0 011-1h6a1 1 0 011 1v2m2 0v14a1 1 0 01-1 1H7a1 1 0 01-1-1V6M10 11v6M14 11v6" /></svg>
          </button>
        </div>
      ))}
      <button type="button" className={styles.createBtnGhost} disabled={disabled}
        onClick={() => { const next = [...splits, 0]; setSplits(next); onSave(next); }}>+ Add place</button>
      {splits.length > 0 && total !== 100 && (
        <p className={styles.roundFormHint} style={{ color: total > 100 ? "var(--warn, #c2410c)" : undefined }}>Splits total {total}% (should be 100%).</p>
      )}
    </div>
  );
}

