export default function ContestPayouts({ base, contestType, initialSplits, feeCents, participantCount, teamSize }: {
  base: string;
  contestType: ContestType;
  initialSplits: number[];
  feeCents: number;
  participantCount: number;
  teamSize: number | null;
}) {
  const [open, setOpen] = useState(false);
  const [splits, setSplits] = useState<number[]>(initialSplits);
  const [busy, setBusy] = useState(false);
  const potCents = feeCents * participantCount;
  const payouts = computePlacePayouts(potCents, splits.map((pct, i) => ({ place: i + 1, kind: "percentage", amount: pct })));
  const team = isTeamContest(contestType);

  async function saveSplits(next: number[]) {
    setSplits(next); setBusy(true);
    try {
      await fetch(base, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ payout_splits: next.map((pct, i) => ({ place: i + 1, kind: "percentage", amount: pct })) }) });
    } finally { setBusy(false); }
  }

  return (
    <div className={styles.cscAcc} data-open={open || undefined} style={{ marginTop: 16 }}>
      <button type="button" className={styles.cscAccHead} onClick={() => setOpen((v) => !v)} aria-expanded={open}>
        <span className={styles.cscAllMain}>
