          <span className={styles.cscAllPlayers}>{potCents > 0 ? `Pot ${money(potCents)}` : "% of pot per place"}</span>
        </span>
        <svg className={styles.cscAccChevron} data-open={open || undefined} width="18" height="18" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.8} d="M6 9l6 6 6-6" /></svg>
      </button>
      {open && (
        <div className={styles.cscAccBody}>
          <label className={styles.label}>Payout splits (% of pot)</label>
          <PayoutSplitsEditor value={splits} onSave={saveSplits} disabled={busy} />
          {potCents > 0 ? (
            <div style={{ marginTop: 12 }}>
              <p className={styles.roundFormHint} style={{ marginTop: 0 }}>Pot: buy-in × {participantCount} in = <strong style={{ color: "var(--brand)" }}>{money(potCents)}</strong></p>
              {payouts.map((p) => {
                const perMember = team && teamSize && teamSize > 1 ? splitAmongMembers(p.amountCents, teamSize)[0] : null;
                return (
                  <p key={p.place} className={styles.roundFormHint} style={{ marginTop: 2 }}>
