export interface PayoutSplit { place: number; kind: string; amount: number } // amount = % of pot
export interface PlacePayout { place: number; percentage: number; amountCents: number }

const ROUND_TO_CENTS = 500; // pay out in whole $5 bills

/** Split the pot by %-of-pot, each place floored to $5, remainder handed out $5 at a time from 1st down. */
export function computePlacePayouts(potCents: number, splits: PayoutSplit[] | null | undefined): PlacePayout[] {
  if (!Number.isFinite(potCents) || potCents <= 0 || !splits?.length) return [];
  const percents = splits
    .filter((s) => s.kind === "percentage")
    .map((s) => ({ place: s.place, percentage: Math.max(0, Math.min(100, Number(s.amount) || 0)) }))
    .sort((a, b) => a.place - b.place);
  if (!percents.length) return [];

  const results = percents.map((p) => ({
    place: p.place, percentage: p.percentage,
    amountCents: Math.floor((potCents * p.percentage) / 100 / ROUND_TO_CENTS) * ROUND_TO_CENTS,
  }));
  let remaining = Math.max(0, potCents - results.reduce((s, r) => s + r.amountCents, 0));
  for (const r of results) {
    if (remaining >= ROUND_TO_CENTS) { r.amountCents += ROUND_TO_CENTS; remaining -= ROUND_TO_CENTS; }
    else break;
  }
  return results;
}

