// A place's cut can be a % of the pot, a fixed dollar amount (stored in cents), or the
// remainder (whatever's left after the fixed + % places).
export type PayoutKind = "percentage" | "fixed" | "remainder";
export interface PayoutSplit { place: number; kind: PayoutKind | string; amount: number } // amount: % (percentage) | cents (fixed) | ignored (remainder)
export interface PlacePayout { place: number; kind: PayoutKind; amountCents: number }

const ROUND_TO_CENTS = 500; // pay out in whole $5 bills

/**
 * Resolve each place to a dollar amount. Fixed places take their exact amount; percentage
 * places take %-of-pot floored to $5; remainder place(s) split whatever's left evenly. If
 * there's no remainder place, the $5 rounding leftover is handed to percentage places top-down.
 */
export function computePlacePayouts(potCents: number, splits: PayoutSplit[] | null | undefined): PlacePayout[] {
  if (!splits?.length) return [];
  const rows = [...splits].sort((a, b) => a.place - b.place);
  const pot = Math.max(0, Number(potCents) || 0);

  const fixedCents = (s: PayoutSplit) => (s.kind === "fixed" ? Math.max(0, Math.round(Number(s.amount) || 0)) : 0);
  const pctCents = (s: PayoutSplit) => (s.kind === "percentage" && pot > 0 ? Math.floor((pot * Math.max(0, Math.min(100, Number(s.amount) || 0))) / 100 / ROUND_TO_CENTS) * ROUND_TO_CENTS : 0);

  const fixedTotal = rows.reduce((t, s) => t + fixedCents(s), 0);
  const pctTotal = rows.reduce((t, s) => t + pctCents(s), 0);
  const remainderPlaces = rows.filter((s) => s.kind === "remainder");
  const remainderEach = remainderPlaces.length ? splitAmongMembers(Math.max(0, pot - fixedTotal - pctTotal), remainderPlaces.length) : [];

  let ri = 0;
  const results: PlacePayout[] = rows.map((s) => {
    const kind = (s.kind === "fixed" || s.kind === "remainder" ? s.kind : "percentage") as PayoutKind;
    const amountCents = kind === "fixed" ? fixedCents(s) : kind === "remainder" ? (remainderEach[ri++] ?? 0) : pctCents(s);
    return { place: s.place, kind, amountCents };
  });

  // No explicit remainder place → hand the $5 rounding leftover to percentage places, top-down.
  if (!remainderPlaces.length && pot > 0) {
    let leftover = Math.max(0, pot - results.reduce((t, r) => t + r.amountCents, 0));
    for (const r of results) {
      if (leftover < ROUND_TO_CENTS) break;
      if (r.kind === "percentage") { r.amountCents += ROUND_TO_CENTS; leftover -= ROUND_TO_CENTS; }
    }
  }
  return results;
}

